import type { BoardState } from '../types/shogi';
import type { EvaluationPresetComparisonResult } from '../domain/shogi/evaluationPresetComparison';
import { SEARCH_EVALUATION_PRESET_IDS } from '../domain/shogi/searchEvaluationPresets';
import { getLegalActions } from '../domain/shogi/legalActions';
import { cloneBoardState } from '../domain/shogi/replay';
import { getDisplayEvaluationBreakdown } from './searchEvaluationBreakdownValidation';
import { validateAndFormatPrincipalVariation } from './searchPrincipalVariation';
import { evaluateNoLegalActionsPositionBreakdown } from '../domain/shogi/twoPlyMinimaxAi';

/** BoardState consists solely of cloneable record data; normalize optional fields. */
export function isSameComparisonPosition(left: BoardState, right: BoardState): boolean {
  try {
    return JSON.stringify(cloneBoardState(left)) === JSON.stringify(cloneBoardState(right));
  } catch {
    return false;
  }
}

/** Fail before publishing; only no-action roots need a terminal consistency query. */
export function validateEvaluationPresetComparison(
  state: BoardState, depth: number, value: unknown,
): asserts value is readonly EvaluationPresetComparisonResult[] {
  const invalid = () => { throw new Error('3プリセットの比較結果を検証できませんでした。'); };
  if (!Array.isArray(value) || value.length !== SEARCH_EVALUATION_PRESET_IDS.length) return invalid();
  const legalCount = getLegalActions(state).length;
  for (const [index, entry] of (value as unknown[]).entries()) {
    if (typeof entry !== 'object' || entry === null) return invalid();
    const result = entry as EvaluationPresetComparisonResult;
    if (!result || result.presetId !== SEARCH_EVALUATION_PRESET_IDS[index] || result.depth !== depth ||
      !Array.isArray(result.principalVariation) || result.principalVariation.length > depth ||
      !(['rootLegalActionCount', 'visitedPositionCount', 'cutoffCount', 'skippedActionCount'] as const).every(
        (key) => Number.isSafeInteger(result[key]) && result[key] >= 0) ||
      result.rootLegalActionCount !== legalCount ||
      !Number.isFinite(result.elapsedMilliseconds) || result.elapsedMilliseconds < 0) return invalid();
    // An unadjudicated no-action root can carry a decisive terminal evaluation.
    const noAction = result.selectedAction === null && legalCount === 0;
    if (!getDisplayEvaluationBreakdown(result.evaluationBreakdown,
      noAction ? result.evaluationBreakdown?.total : result.selectedEvaluation)) return invalid();
    if (noAction) {
      const expected = evaluateNoLegalActionsPositionBreakdown(state, state.turn);
      const selected = state.status === 'ended' || expected.terminal === null ? null : expected.total;
      if (result.selectedEvaluation !== selected || result.evaluationBreakdown.terminal !== expected.terminal || result.principalVariation.length !== 0 ||
        result.visitedPositionCount !== 0 || result.cutoffCount !== 0 || result.skippedActionCount !== 0) return invalid();
    } else if (!validateAndFormatPrincipalVariation(state, result, depth, true)) return invalid();
  }
}

import type { BoardState } from '../types/shogi';
import { createComparisonSnapshot, type EvaluationPresetComparisonResult } from '../domain/shogi/evaluationPresetComparison';
import type { EvaluationPresetComparisonWorkerRequest, EvaluationPresetComparisonWorkerResponse } from '../workers/evaluationPresetComparisonWorkerProtocol';
import { createSearchWorker, createSearchWorkerRequestId, runSearchWorkerJob, type SearchWorkerLike } from './searchWorkerJob';
import { isSameComparisonPosition, validateEvaluationPresetComparison } from './evaluationPresetComparisonValidation';

export function createEvaluationPresetComparisonWorkerClient(dependencies: {
  workerFactory?: () => SearchWorkerLike<EvaluationPresetComparisonWorkerRequest>;
  requestIdFactory?: () => string;
} = {}) {
  return {
    run(state: BoardState, depth: number, signal?: AbortSignal): Promise<readonly EvaluationPresetComparisonResult[]> {
      const snapshot = createComparisonSnapshot(state);
      return runSearchWorkerJob(dependencies.workerFactory ?? createSearchWorker<EvaluationPresetComparisonWorkerRequest>, () => ({ type: 'compare-evaluation-presets' as const,
        requestId: dependencies.requestIdFactory?.() ?? createSearchWorkerRequestId(), state: snapshot, depth,
      }), (data) => {
        const response = data as EvaluationPresetComparisonWorkerResponse;
        if (response.type === 'evaluation-preset-comparison-failed') throw new Error(response.errorMessage);
        if (response.type !== 'evaluation-preset-comparison-succeeded' || response.depth !== depth ||
          !isSameComparisonPosition(snapshot, response.state)) throw new Error('比較の開始局面または深さが一致しません。');
        validateEvaluationPresetComparison(snapshot, depth, response.results);
        return response.results;
      }, signal);
    },
  };
}

export function runEvaluationPresetComparisonInWorker(state: BoardState, depth: number, signal?: AbortSignal) {
  return createEvaluationPresetComparisonWorkerClient().run(state, depth, signal);
}

