import type { SearchEvaluationBreakdown } from '../domain/shogi';

/** Validate received data only; never evaluate a board in the UI. */
export function getDisplayEvaluationBreakdown(
  value: unknown,
  selectedEvaluation: number | null,
): SearchEvaluationBreakdown | null {
  if (typeof value !== 'object' || value === null ||
    !('total' in value) || !('material' in value) || !('pieceSquare' in value) ||
    !('kingSafety' in value) || !('undefendedPieceSafety' in value) || !('terminal' in value)) return null;
  const { total, material, pieceSquare, kingSafety, undefendedPieceSafety, terminal } = value;
  if (typeof total !== 'number' || Number.isNaN(total) || total !== selectedEvaluation ||
    typeof material !== 'number' || !Number.isFinite(material) ||
    typeof pieceSquare !== 'number' || !Number.isFinite(pieceSquare) ||
    typeof kingSafety !== 'number' || !Number.isFinite(kingSafety) ||
    typeof undefendedPieceSafety !== 'number' || !Number.isFinite(undefendedPieceSafety)) return null;
  if (terminal === null) {
    if (!Number.isFinite(total) || total !== material + pieceSquare + kingSafety + undefendedPieceSafety) return null;
  } else {
    if (terminal !== 'win' && terminal !== 'loss' && terminal !== 'draw') return null;
    const expectedTotal = terminal === 'win' ? Infinity : terminal === 'loss' ? -Infinity : 0;
    if (total !== expectedTotal || material !== 0 || pieceSquare !== 0 || kingSafety !== 0 || undefendedPieceSafety !== 0) return null;
  }
  return { total, material, pieceSquare, kingSafety, undefendedPieceSafety, terminal };
}

src/application/searchPrincipalVariation:
import type { BoardState } from '../types/shogi';
import type { SearchEvaluationBreakdown } from '../domain/shogi/twoPlyMinimaxAi';
import { areLegalActionsEqual, cloneBoardState, executeLegalAction, getLegalActions,
  generateMoveNotation, generateDropNotation, type LegalAction, type AlphaBetaSearchResult } from '../domain/shogi';

export function formatLegalActionNotation(state: BoardState, action: LegalAction): string {
  if (action.kind === 'move') {
    const piece = state.squares[action.from.row]?.[action.from.col]?.piece;
    if (!piece) throw new Error('A legal move action must have a source piece.');
    return generateMoveNotation(state.turn, piece, action.to, action.promotion);
  }

  const hand = state.turn === 'sente' ? state.senteHand : state.goteHand;
  const piece = hand.find((candidate) => candidate.id === action.pieceId);
  if (!piece) throw new Error('A legal drop action must have a hand piece.');
  return generateDropNotation(state.turn, piece, action.to);
}

/**
 * Treat a Worker result as untrusted at the UI boundary. The returned notation
 * is generated while replaying a clone, so every later PV action sees the
 * position created by the earlier action.
 */
export function validateAndFormatPrincipalVariation(
  state: BoardState,
  result: Pick<AlphaBetaSearchResult, 'selectedAction' | 'principalVariation'> & {
    evaluationBreakdown: SearchEvaluationBreakdown | null;
  },
  depth: number,
  requireSearchLeaf = false,
): string[] | null {
  if (!result.selectedAction || !Array.isArray(result.principalVariation) ||
    !Number.isInteger(depth) || depth < 1 ||
    result.principalVariation.length === 0 ||
    result.principalVariation.length > depth) {
    return null;
  }

  try {
    if (!areLegalActionsEqual(result.principalVariation[0], result.selectedAction)) return null;
    let replayState = cloneBoardState(state);
    const notations: string[] = [];
    for (const action of result.principalVariation) {
      if (!getLegalActions(replayState).some((legalAction) => areLegalActionsEqual(legalAction, action))) {
        return null;
      }
      notations.push(formatLegalActionNotation(replayState, action));
      const execution = executeLegalAction(replayState, action, { proposer: 'local_ai' });
      if (execution.type !== 'applied') return null;
      replayState = execution.state;
    }
    if (requireSearchLeaf) {
      if (notations.length < depth && replayState.status !== 'ended' && getLegalActions(replayState).length > 0) return null;
      if (replayState.status === 'ended' && !replayState.result) return null;
      const terminal = replayState.status !== 'ended' ? null : replayState.result!.winner === null
        ? 'draw' : replayState.result!.winner === state.turn ? 'win' : 'loss';
      if (result.evaluationBreakdown?.terminal !== terminal) return null;
    }
    return notations;
  } catch {
    return null;
  }
}

src/application/searchWorkerJob.ts:
/** Shared one-request/one-Worker lifecycle; no synchronous fallback. */
export interface SearchWorkerLike<TRequest> {
  addEventListener(type: 'message', listener: (event: MessageEvent<unknown>) => void): void;
  addEventListener(type: 'error', listener: (event: ErrorEvent) => void): void;
  addEventListener(type: 'messageerror', listener: (event: MessageEvent<unknown>) => void): void;
  postMessage(message: TRequest): void;
  terminate(): void;
}
export class TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerError extends Error {
  constructor(message: string, name = 'TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerError') {
    super(message);
    this.name = name;
  }
}

/** Identifies a search cancelled by the caller's AbortSignal. */
export class TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerAbortError extends Error {
  constructor() {
    super('Time-limited iterative deepening alpha-beta Worker search was aborted.');
    this.name = 'AbortError';
  }
}

export function createSearchWorker<TRequest>(): SearchWorkerLike<TRequest> {
  if (typeof Worker === 'undefined') {
    throw new TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerError(
      'Web Worker is not available in this environment.'
    );
  }

  return new Worker(
    new URL('../workers/timeLimitedIterativeDeepeningAlphaBeta.worker.ts', import.meta.url),
    { type: 'module' }
  );
}

export function createSearchWorkerRequestId(): string {
  return globalThis.crypto?.randomUUID?.() ??
    `time-limited-iterative-alpha-beta-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

export function runSearchWorkerJob<TRequest extends { requestId: string }, TResult>(
  workerFactory: () => SearchWorkerLike<TRequest>,
  createRequest: () => TRequest,
  acceptResponse: (response: object) => TResult,
  signal?: AbortSignal,
): Promise<TResult> {
  if (signal?.aborted) {
    return Promise.reject(new TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerAbortError());
  }

  return new Promise<TResult>((resolve, reject) => {
    let worker: SearchWorkerLike<TRequest>;
    try {
      worker = workerFactory();
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Web Worker could not be created.';
      reject(new TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerError(message));
      return;
    }

    let settled = false;
    let abortListenerAttached = false;
    const abort = (): void => {
      finish(() => reject(new TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerAbortError()));
    };
    const removeAbortListener = (): void => {
      if (!signal || !abortListenerAttached) return;
      signal.removeEventListener('abort', abort);
      abortListenerAttached = false;
    };
    const finish = (completion: () => void): void => {
      if (settled) return;
      settled = true;
      removeAbortListener();
      worker.terminate();
      completion();
    };
    const fail = (message: string, name?: string): void => {
      finish(() => reject(new TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerError(message, name)));
    };

    if (signal?.aborted) {
      abort();
      return;
    }

    let request: TRequest;
    try {
      request = createRequest();
      worker.addEventListener('message', (event) => {
        if (settled) return;
        try {
          const response = event.data;
          if (typeof response !== 'object' || response === null ||
            !('requestId' in response) || response.requestId !== request.requestId) {
            throw new TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerError(
              'Worker response requestId did not match the submitted request.', 'WorkerProtocolError');
          }
          const result = acceptResponse(response);
          finish(() => resolve(result));
        } catch (error) {
          fail(error instanceof Error ? error.message : 'Malformed Worker response.',
            error instanceof Error ? error.name : 'WorkerProtocolError');
        }
      });
      worker.addEventListener('error', (event) => {
        fail(event.message || 'Web Worker reported an error.');
      });
      worker.addEventListener('messageerror', () => {
        fail('Web Worker could not deserialize a message.', 'WorkerMessageError');
      });

      if (settled) return;

      if (signal) {
        abortListenerAttached = true;
        signal.addEventListener('abort', abort, { once: true });
        if (settled) return;
        if (signal.aborted) {
          abort();
          return;
        }
      }

      if (signal?.aborted) {
        abort();
        return;
      }
      worker.postMessage(request);
    } catch (error) {
      fail(error instanceof Error ? error.message : 'Web Worker request could not be posted.');
    }
  });
}

