import type { SearchEvaluationPresetId } from '../../domain/shogi/searchEvaluationPresets';
import type { PresetTimeLimitedSearchResult } from '../../workers/timeLimitedIterativeDeepeningAlphaBetaWorkerProtocol';
import type {
  TwoPlyMinimaxSearchResult,
} from '../../domain/shogi';

import type { Player } from '../../types/shogi';
import { formatSenteEvaluation } from './searchEvaluationDisplay';
import { getGameResultDisplay } from './gameResultDisplay';

export type AiSearchDisplay =
  | {
      kind: 'two-ply';
      perspective: Player;
      result: TwoPlyMinimaxSearchResult & { readonly evaluationPresetId: SearchEvaluationPresetId };
      selectedNotation: string;
      candidateNotations: readonly string[];
    }
  | {
      kind: 'time-limited-worker';
      perspective: Player;
      result: PresetTimeLimitedSearchResult;
      selectedNotation: string;
      principalVariationNotations: readonly string[];
    };

interface AiSearchResultPanelProps {
  search: AiSearchDisplay;
}

/** A compact presentation of the latest synchronous or Worker AI search. */
export function AiSearchResultPanel({ search }: AiSearchResultPanelProps) {
  if (search.kind === 'time-limited-worker') {
    const { result } = search;
    const quiescenceLabel = result.quiescenceMaxTacticalDepth === null
      ? '無効' : `追加${result.quiescenceMaxTacticalDepth}手`;
    return (
      <section
        aria-labelledby="ai-search-result-title"
        className="w-full min-w-0 rounded border border-sky-800/70 bg-sky-950/30 p-3 shadow-inner xl:max-w-sm"
      >
        <h2 id="ai-search-result-title" className="font-serif text-sm tracking-[0.12em] text-sky-100">
          AI思考結果
        </h2>
        <p className="mt-1 text-xs text-stone-300">時間制限付き反復深化αβ探索</p>
        {result.resultSource === 'partial-root' && <p className="mt-1 text-xs text-stone-300">選択候補の評価・PVです。全合法手の比較は未完了です。</p>}
        <dl className="mt-2 grid grid-cols-[minmax(0,2fr)_minmax(0,1fr)] gap-x-3 gap-y-1 text-xs">
          <dt className="text-stone-400">完了深さ</dt>
          <dd className="text-sky-100">{result.completedDepth}</dd>
          <dt className="text-stone-400">着手の出所</dt>
          <dd className="text-sky-100">{result.resultSource === 'ended-position' ? '終局済み' : result.resultSource === 'no-legal-actions' ? '合法手なし' : result.resultSource === 'fallback' ? '合法手 fallback' : result.resultSource === 'partial-root' ? '部分探索・深さ1未完了' : '完了した探索'}</dd>
          {result.resultSource === 'ended-position' && result.terminalResult && <>
            <dt className="text-stone-400">終局結果</dt>
            <dd className="text-sky-100">{getGameResultDisplay(result.terminalResult).panelText}</dd>
          </>}
          {result.resultSource === 'partial-root' && result.partialRoot && <>
            <dt className="text-stone-400">期限内確定候補／合法手数</dt>
            <dd className="text-sky-100">{result.partialRoot.completedRootCandidateCount} / {result.rootLegalActionCount}</dd>
            <dt className="text-stone-400">exact候補数</dt>
            <dd className="text-sky-100">{result.partialRoot.exactRootCandidateCount}</dd>
          </>}
          <dt className="text-stone-400">指定最大深さ</dt>
          <dd className="text-sky-100">{result.requestedMaxDepth}</dd>
          <dt className="text-stone-400">API全体の経過時間</dt>
          <dd className="text-sky-100">{result.elapsedMilliseconds.toFixed(2)} ms</dd>
          <dt className="text-stone-400">静止探索</dt>
          <dd className="text-sky-100">{quiescenceLabel}</dd>
          <dt className="text-stone-400">最深完了反復の調査局面数</dt>
          <dd className="text-sky-100">{result.visitedPositionCount}</dd>
          <dt className="text-stone-400">最深完了反復の枝刈り回数</dt>
          <dd className="text-sky-100">{result.cutoffCount}</dd>
          <dt className="text-stone-400">最深完了反復の未調査候補手数</dt>
          <dd className="text-sky-100">{result.skippedActionCount}</dd>
          <dt className="text-stone-400">全完了反復合計の調査局面数</dt>
          <dd className="text-sky-100">{result.totalVisitedPositionCount}</dd>
          <dt className="text-stone-400">全完了反復合計の枝刈り回数</dt>
          <dd className="text-sky-100">{result.totalCutoffCount}</dd>
          <dt className="text-stone-400">全完了反復合計の未調査候補手数</dt>
          <dd className="text-sky-100">{result.totalSkippedActionCount}</dd>
        </dl>
        <div className="mt-3 border-t border-sky-900/80 pt-2">
          <h3 className="text-xs font-medium text-stone-300">静止探索の量（通常探索とは別）</h3>
          <dl className="mt-1 grid grid-cols-[minmax(0,2fr)_minmax(0,1fr)] gap-x-3 gap-y-1 text-xs">
            <dt className="text-stone-400">最深完了反復の静止探索葉数</dt>
            <dd className="text-sky-100">{result.quiescenceLeafCount}</dd>
            <dt className="text-stone-400">最深完了反復の静止探索調査局面数</dt>
            <dd className="text-sky-100">{result.quiescenceVisitedPositionCount}</dd>
            <dt className="text-stone-400">最深完了反復の静止探索枝刈り回数</dt>
            <dd className="text-sky-100">{result.quiescenceCutoffCount}</dd>
            <dt className="text-stone-400">最深完了反復の静止探索未調査候補手数</dt>
            <dd className="text-sky-100">{result.quiescenceSkippedActionCount}</dd>
            <dt className="text-stone-400">全完了反復合計の静止探索葉数</dt>
            <dd className="text-sky-100">{result.totalQuiescenceLeafCount}</dd>
            <dt className="text-stone-400">全完了反復合計の静止探索調査局面数</dt>
            <dd className="text-sky-100">{result.totalQuiescenceVisitedPositionCount}</dd>
            <dt className="text-stone-400">全完了反復合計の静止探索枝刈り回数</dt>
            <dd className="text-sky-100">{result.totalQuiescenceCutoffCount}</dd>
            <dt className="text-stone-400">全完了反復合計の静止探索未調査候補手数</dt>
            <dd className="text-sky-100">{result.totalQuiescenceSkippedActionCount}</dd>
          </dl>
        </div>
      </section>
    );
  }

  const { result, candidateNotations } = search;
  return (
    <section
      aria-labelledby="ai-search-result-title"
      className="w-full min-w-0 rounded border border-violet-800/70 bg-violet-950/30 p-3 shadow-inner xl:max-w-sm"
    >
      <h2 id="ai-search-result-title" className="font-serif text-sm tracking-[0.12em] text-violet-100">
        AI思考結果
      </h2>
      <dl className="mt-2 grid grid-cols-[minmax(0,2fr)_minmax(0,1fr)] gap-x-3 gap-y-1 text-xs">
        <dt className="text-stone-400">合法手数</dt>
        <dd className="text-violet-100">{result.rootLegalActionCount}</dd>
        <dt className="text-stone-400">調査局面数</dt>
        <dd className="text-violet-100">{result.visitedPositionCount}</dd>
        <dt className="text-stone-400">読みの深さ</dt>
        <dd className="text-violet-100">{result.depth}</dd>
        <dt className="text-stone-400">経過時間</dt>
        <dd className="text-violet-100">{result.elapsedMilliseconds.toFixed(2)} ms</dd>
      </dl>
      <div className="mt-3 border-t border-violet-900/80 pt-2">
        <h3 className="text-xs font-medium text-stone-300">上位候補手</h3>
        <p className="mt-1 text-xs text-stone-400">先手基準：＋は先手有利、−は後手有利</p>
        <ol className="mt-1 space-y-1 text-xs text-violet-100">
          {result.topCandidates.map((candidate, index) => (
            <li key={`${candidateNotations[index]}-${index}`} className="flex flex-wrap justify-between gap-3 break-words">
              <span>{candidateNotations[index]}</span>
              <span>先手 {formatSenteEvaluation(candidate.evaluation, search.perspective)}</span>
            </li>
          ))}
        </ol>
      </div>
    </section>
  );
}

import React, { useEffect, useRef } from 'react';

interface BranchReplayDialogProps {
  kind: 'start' | 'return';
  historyIndex?: number;
  onConfirm: () => void;
  onCancel: () => void;
}

export const BranchReplayDialog: React.FC<BranchReplayDialogProps> = ({
  kind,
  historyIndex,
  onConfirm,
  onCancel,
}) => {
  const dialogRef = useRef<HTMLDivElement>(null);
  const cancelButtonRef = useRef<HTMLButtonElement>(null);
  const isStart = kind === 'start';
  const positionLabel = historyIndex === 0 ? '初期局面' : `第${historyIndex}手後の局面`;

  useEffect(() => {
    cancelButtonRef.current?.focus();
  }, []);

  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      onCancel();
      return;
    }
    if (event.key !== 'Tab') return;
    const buttons = Array.from(
      dialogRef.current?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)') ?? []
    );
    if (buttons.length === 0) return;
    const first = buttons[0];
    const last = buttons.at(-1)!;
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 px-4 backdrop-blur-[2px]"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) {
          event.preventDefault();
          onCancel();
        }
      }}
    >
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="branch-replay-dialog-title"
        aria-describedby="branch-replay-dialog-description"
        onKeyDown={handleKeyDown}
        className="w-full max-w-md rounded-md border border-amber-700/60 bg-[#211811] p-5 text-center shadow-[0_24px_80px_rgba(0,0,0,0.78),inset_0_1px_rgba(255,255,255,0.05)]"
      >
        <h2 id="branch-replay-dialog-title" className="font-serif text-xl font-semibold tracking-[0.1em] text-amber-100">
          {isStart ? 'ここから指し直しますか？' : '本譜へ戻りますか？'}
        </h2>
        <p id="branch-replay-dialog-description" className="mt-2 text-sm leading-6 text-stone-300">
          {isStart
            ? `${positionLabel}から指し直します。本譜は変更されません。`
            : '現在の検討手順はこのセッション内に保持したまま、本譜の現在局面へ切り替えます。'}
        </p>
        <div className="mt-5 flex flex-wrap justify-center gap-3">
          <button
            type="button"
            onClick={onConfirm}
            className="min-w-32 rounded border border-sky-700/70 bg-sky-950/70 px-4 py-2 font-serif text-sky-100 outline-none transition hover:bg-sky-900/80 focus-visible:ring-2 focus-visible:ring-amber-300"
          >
            {isStart ? 'ここから指し直す' : '本譜へ戻る'}
          </button>
          <button
            ref={cancelButtonRef}
            type="button"
            onClick={onCancel}
            className="min-w-24 rounded border border-amber-600/60 bg-amber-900/40 px-4 py-2 font-serif text-amber-50 outline-none transition hover:bg-amber-800/55 focus-visible:ring-2 focus-visible:ring-amber-300"
          >
            キャンセル
          </button>
        </div>
      </div>
    </div>
  );
};

