import React, { useState, useEffect, useRef } from 'react';
import { BoardSquare, BoardStatus, FILE_NUMBERS, MoveRecord, PieceType, RANK_KANJI, getPieceDisplayInfo, getSquareAriaLabel } from '../../types/shogi';
import { Piece } from './Piece';

interface ShogiBoardProps {
  squares: BoardSquare[][];
  status?: BoardStatus;
  className?: string;
  selectedSquare?: { row: number; col: number } | null;
  candidateSquares?: Array<{ row: number; col: number }>;
  candidateKind?: 'move' | 'drop' | null;
  dropPieceType?: PieceType | null;
  lastMove?: MoveRecord | null;
  onSquareClick?: (square: BoardSquare) => void;
  focusRequest?: { row: number; col: number; requestId: number } | null;
}

// Default initial focus position: 7七 (row 6, col 2 -> 7筋 7段)
// In traditional Shogi research, 7七 (▲7六歩 or ▲7七...) is a standard opening file/square.
const DEFAULT_INITIAL_FOCUS = { row: 6, col: 2 };

export const ShogiBoard: React.FC<ShogiBoardProps> = ({
  squares,
  status = 'preparation',
  className = '',
  selectedSquare = null,
  candidateSquares = [],
  candidateKind = null,
  dropPieceType = null,
  lastMove = null,
  onSquareClick,
  focusRequest = null,
}) => {
  const isInteractive = typeof onSquareClick === 'function';
  const dropPieceName = dropPieceType
    ? getPieceDisplayInfo(dropPieceType, 'sente', false).fullName
    : '持ち駒';

  // Roving tabindex position management
  // Priority: 1. selectedSquare if provided and within bounds, 2. DEFAULT_INITIAL_FOCUS (7七: row 6, col 2)
  const [focusedSquare, setFocusedSquare] = useState<{ row: number; col: number }>(() => {
    if (
      selectedSquare &&
      selectedSquare.row >= 0 &&
      selectedSquare.row < 9 &&
      selectedSquare.col >= 0 &&
      selectedSquare.col < 9
    ) {
      return { row: selectedSquare.row, col: selectedSquare.col };
    }
    return DEFAULT_INITIAL_FOCUS;
  });

  // Track if selectedSquare changed from props
  useEffect(() => {
    if (
      selectedSquare &&
      selectedSquare.row >= 0 &&
      selectedSquare.row < 9 &&
      selectedSquare.col >= 0 &&
      selectedSquare.col < 9
    ) {
      setFocusedSquare({ row: selectedSquare.row, col: selectedSquare.col });
    }
  }, [selectedSquare]);

  // Scoped references for cells within the board (to avoid global querySelector)
  const cellRefs = useRef<Map<string, HTMLDivElement>>(new Map());

  // Focus the target cell within the board without global queries
  const focusCell = (row: number, col: number) => {
    const key = `${row}-${col}`;
    const el = cellRefs.current.get(key);
    if (el) {
      el.focus();
    }
  };

  useEffect(() => {
    if (!focusRequest) return;
    setFocusedSquare({ row: focusRequest.row, col: focusRequest.col });
    focusCell(focusRequest.row, focusRequest.col);
  }, [focusRequest]);

  const handleKeyDown = (e: React.KeyboardEvent, square: BoardSquare) => {
    if (!isInteractive) return;

    let targetRow = square.row;
    let targetCol = square.col;
    let handled = false;

    switch (e.key) {
      case 'ArrowUp':
        // Move up (decrement row, stay bounded >= 0)
        targetRow = Math.max(0, square.row - 1);
        handled = true;
        break;
      case 'ArrowDown':
        // Move down (increment row, stay bounded <= 8)
        targetRow = Math.min(8, square.row + 1);
        handled = true;
        break;
      case 'ArrowLeft':
        // Move left (decrement col, stay bounded >= 0)
        targetCol = Math.max(0, square.col - 1);
        handled = true;
        break;
      case 'ArrowRight':
        // Move right (increment col, stay bounded <= 8)
        targetCol = Math.min(8, square.col + 1);
        handled = true;
        break;
      case 'Enter':
      case ' ': // Space key
        e.preventDefault();
        onSquareClick(square);
        return;
      default:
        return;
    }

    if (handled) {
      e.preventDefault(); // Prevent page scroll on arrow keys
      if (targetRow !== square.row || targetCol !== square.col) {
        setFocusedSquare({ row: targetRow, col: targetCol });
        focusCell(targetRow, targetCol);
      }
    }
  };

  const handleCellClick = (square: BoardSquare) => {
    if (!isInteractive) return;
    setFocusedSquare({ row: square.row, col: square.col });
    onSquareClick(square);
  };

  return (
    <div
      id="shogi-board-wrapper"
      className={`relative inline-block select-none max-w-full ${className}`}
      data-board-status={status}
    >
      {/* Outer Container with Coordinate Labels */}
      <div className="flex flex-col items-center">
        {/* Top File Coordinates (9 to 1) */}
        <div
          aria-hidden="true"
          className="grid grid-cols-9 w-[min(82vw,510px)] sm:w-[510px] px-3 sm:px-4 mb-1 text-center font-serif text-[11px] sm:text-xs font-semibold text-amber-200/60 tracking-wider"
        >
          {FILE_NUMBERS.map((file) => (
            <div key={`file-coord-${file}`} className="flex justify-center items-center">
              <span>{file}</span>
            </div>
          ))}
        </div>

        {/* Board Main Body with Side Rank Coordinates */}
        <div className="flex items-stretch justify-center">
          {/* 3D Solid Wooden Board Chassis (厚みのある本榧盤) */}
          <div
            id="shogi-board-frame"
            className="relative rounded-sm transition-all duration-300"
            style={{
              boxShadow: `
                0 30px 60px -15px rgba(0, 0, 0, 0.9),
                0 15px 25px -5px rgba(0, 0, 0, 0.7),
                0 0 1px 1px rgba(255, 100, 50, 0.25)
              `,
            }}
          >
            {/* Ambient Warm Neon Rim Reflection (top edge glow as in reference image) */}
            <div
              aria-hidden="true"
              className="absolute -top-[1px] inset-x-0 h-[2px] bg-gradient-to-r from-rose-600/30 via-orange-500/80 to-rose-600/30 rounded-t-sm shadow-[0_0_12px_rgba(249,115,22,0.6)] z-20 pointer-events-none"
            />
            {/* Left & Right Rim Light Accents */}
            <div
              aria-hidden="true"
              className="absolute inset-y-0 -left-[1px] w-[1.5px] bg-gradient-to-b from-orange-500/70 via-rose-600/30 to-transparent pointer-events-none z-20"
            />
            <div
              aria-hidden="true"
              className="absolute inset-y-0 -right-[1px] w-[1.5px] bg-gradient-to-b from-orange-500/70 via-rose-600/30 to-transparent pointer-events-none z-20"
            />

            {/* Board Top Surface & Side Depth Wrapper */}
            <div className="relative flex flex-col rounded-sm overflow-hidden bg-[#b87d35]">
              {/* Top Playing Surface */}
              <div
                className="relative p-2.5 sm:p-3.5"
                style={{
                  background:
                    'linear-gradient(178deg, #deb06c 0%, #d49f55 30%, #c88f42 70%, #b87c2e 100%)',
                }}
              >
                {/* Natural Vertical Grain Fiber Lines (榧木目・天面) */}
                <div
                  aria-hidden="true"
                  className="absolute inset-0 pointer-events-none opacity-40 mix-blend-multiply"
                  style={{
                    backgroundImage: `
                      repeating-linear-gradient(90deg, transparent 0px, transparent 12px, rgba(120,55,10,0.14) 13px, transparent 14px),
                      repeating-linear-gradient(90.5deg, transparent 0px, transparent 27px, rgba(90,40,5,0.1) 28px, transparent 30px),
                      repeating-linear-gradient(89.5deg, transparent 0px, transparent 55px, rgba(160,80,20,0.12) 56px, transparent 59px),
                      linear-gradient(180deg, rgba(255,255,255,0.25) 0%, transparent 20%, rgba(60,25,5,0.15) 100%)
                    `,
                  }}
                />

                {/* 9x9 Grid Surface with Fine Lacquer Lines */}
                <div
                  id="shogi-grid"
                  role="grid"
                  aria-label="将棋盤 9×9マス"
                  aria-readonly={!isInteractive}
                  className="relative flex flex-col w-[min(78vw,480px)] h-[min(78vw,480px)] sm:w-[480px] sm:h-[480px] rounded-[1px] overflow-hidden"
                  style={{
                    border: '1.5px solid rgba(40, 20, 5, 0.95)',
                    boxShadow: 'inset 0 0 4px rgba(60, 25, 5, 0.4)',
                  }}
                >
                  {squares.map((rowSquares, rowIndex) => (
                    <div
                      key={`grid-row-${rowIndex}`}
                      role="row"
                      aria-label={`${RANK_KANJI[rowIndex]}段目`}
                      className="grid grid-cols-9 flex-1"
                    >
                      {rowSquares.map((square, colIndex) => {
                        const isSelected =
                          selectedSquare?.row === rowIndex && selectedSquare?.col === colIndex;
                        const isCandidate = candidateSquares.some(
                          (c) => c.row === rowIndex && c.col === colIndex
                        );
                        const isLastMoveSource =
                          lastMove?.kind === 'move' &&
                          lastMove.from.row === rowIndex &&
                          lastMove.from.col === colIndex;
                        const isLastMoveDest =
                          lastMove?.to.row === rowIndex && lastMove?.to.col === colIndex;
                        const isRovingTabTarget =
                          isInteractive &&
                          focusedSquare.row === rowIndex &&
                          focusedSquare.col === colIndex;

                        const baseAriaLabel = getSquareAriaLabel(square);
                        const ariaLabel = isCandidate
                          ? candidateKind === 'drop'
                            ? `${baseAriaLabel}、${dropPieceName}を打てる`
                            : square.piece
                              ? `${baseAriaLabel}、移動可能（相手の駒を取る）`
                              : `${baseAriaLabel}、移動可能`
                          : baseAriaLabel;

                        return (
                          <div
                            key={`sq-${square.coordinateLabel}`}
                            id={`square-${square.coordinateLabel}`}
                            ref={(el) => {
                              const key = `${rowIndex}-${colIndex}`;
                              if (el) {
                                cellRefs.current.set(key, el);
                              } else {
                                cellRefs.current.delete(key);
                              }
                            }}
                            role="gridcell"
                            tabIndex={isInteractive ? (isRovingTabTarget ? 0 : -1) : undefined}
                            aria-selected={isSelected ? true : undefined}
                            aria-label={ariaLabel}
                            data-file={square.file}
                            data-rank={square.rank}
                            data-coordinate={square.coordinateLabel}
                            data-candidate={isCandidate ? 'true' : undefined}
                            data-candidate-kind={isCandidate ? candidateKind ?? undefined : undefined}
                            data-selected={isSelected ? 'true' : undefined}
                            data-last-move={isLastMoveDest ? 'dest' : isLastMoveSource ? 'source' : undefined}
                            onClick={isInteractive ? () => handleCellClick(square) : undefined}
                            onKeyDown={isInteractive ? (e) => handleKeyDown(e, square) : undefined}
                            className={`relative flex items-center justify-center aspect-square select-none outline-none ${
                              isInteractive
                                ? 'cursor-pointer hover:bg-amber-400/20 focus-visible:ring-2 focus-visible:ring-amber-300 focus-visible:ring-inset focus-visible:z-30'
                                : 'cursor-default'
                            } ${
                              isSelected
                                ? 'bg-amber-400/35 ring-2 ring-amber-300 z-20'
                                : isCandidate
                                ? square.piece
                                  ? 'bg-rose-500/25 ring-2 ring-rose-400/70 z-20'
                                  : 'bg-amber-300/15'
                                : isLastMoveDest
                                ? 'bg-amber-400/20 ring-1 ring-amber-300/50'
                                : isLastMoveSource
                                ? 'bg-amber-800/20'
                                : ''
                            }`}
                            style={{
                              borderRight:
                                colIndex < 8 ? '1px solid rgba(45, 22, 6, 0.9)' : 'none',
                              borderBottom:
                                rowIndex < 8 ? '1px solid rgba(45, 22, 6, 0.9)' : 'none',
                            }}
                          >
                            {/* Star Dot Marker (星 - 黒漆ドット) on intersections (3-3, 3-6, 6-3, 6-6) */}
                            {square.hasBottomRightStarMarker && (
                              <div
                                aria-hidden="true"
                                data-testid="star-marker"
                                className="absolute -bottom-[2.5px] -right-[2.5px] w-1.5 h-1.5 rounded-full bg-[#1e0e04] shadow-[0_0.5px_1px_rgba(0,0,0,0.9)] z-20 pointer-events-none"
                              />
                            )}

                            {/* Move Candidate Indicator for Empty Square */}
                            {isCandidate && !square.piece && (
                              <div
                                aria-hidden="true"
                                data-testid="move-candidate-dot"
                                className="w-3.5 h-3.5 sm:w-4 sm:h-4 rounded-full bg-amber-300/60 ring-2 ring-amber-400/80 shadow-[0_0_8px_rgba(251,191,36,0.6)] z-20 pointer-events-none transition-transform animate-pulse"
                              />
                            )}

                            {/* Piece Display */}
                            {square.piece && (
                              <Piece
                                piece={square.piece}
                                squareCoordinate={square.coordinateLabel}
                                isSelected={isSelected}
                                isLegalTarget={isCandidate && square.piece.player !== (isSelected ? square.piece.player : undefined)}
                                isLastMove={isLastMoveDest}
                              />
                            )}
                          </div>
                        );
                      })}
                    </div>
                  ))}
                </div>
              </div>

              {/* 3D Front Board Thickness & End-Grain (木口 側面立体ブロック) */}
              <div
                aria-hidden="true"
                className="relative w-full h-5 sm:h-7 pointer-events-none border-t border-amber-950/60"
                style={{
                  background:
                    'linear-gradient(180deg, #996222 0%, #7d4d14 35%, #5d3609 80%, #3e2203 100%)',
                  boxShadow: 'inset 0 1px 2px rgba(255,255,255,0.2), 0 8px 16px rgba(0,0,0,0.8)',
                }}
              >
                {/* Wood End-grain rings & vertical striations */}
                <div
                  className="absolute inset-0 opacity-40 mix-blend-multiply"
                  style={{
                    backgroundImage: `
                      repeating-linear-gradient(90deg, transparent 0px, transparent 6px, rgba(30,12,2,0.4) 7px, transparent 8px),
                      linear-gradient(180deg, rgba(0,0,0,0.1) 0%, rgba(0,0,0,0.7) 100%)
                    `,
                  }}
                />
              </div>
            </div>
          </div>

          {/* Right Rank Coordinates (一 to 九) */}
          <div
            aria-hidden="true"
            className="flex flex-col justify-around py-3 sm:py-4 pl-1.5 sm:pl-2 font-serif text-[11px] sm:text-xs font-semibold text-amber-200/60"
          >
            {RANK_KANJI.map((kanji) => (
              <div
                key={`rank-coord-${kanji}`}
                className="flex items-center justify-center h-full text-center"
              >
                <span>{kanji}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

src/components/shogi/ShogiResearchScreen:
import { validatePartialRoot } from '../../application/partialRootValidation';
import { TIME_LIMITED_QUIESCENCE_COMPARISON_MAX_DEPTH, TIME_LIMITED_QUIESCENCE_COMPARISON_MILLISECONDS } from '../../domain/shogi/timeLimitedQuiescenceComparison';
import { runTimeLimitedQuiescenceComparisonInWorker } from '../../application/timeLimitedQuiescenceComparisonWorkerClient';
import { validateTimeLimitedQuiescenceComparison } from '../../application/timeLimitedQuiescenceComparisonValidation';
import { TimeLimitedQuiescenceComparisonPanel, type TimeLimitedQuiescenceComparisonDisplay } from './TimeLimitedQuiescenceComparisonPanel';
import { QUIESCENCE_COMPARISON_DEPTH } from '../../domain/shogi/quiescenceComparison';
import { runQuiescenceComparisonInWorker } from '../../application/quiescenceComparisonWorkerClient';
import { validateQuiescenceComparison } from '../../application/quiescenceComparisonValidation';
import { QuiescenceComparisonPanel, type QuiescenceComparisonDisplay } from './QuiescenceComparisonPanel';
import { EVALUATION_PRESET_COMPARISON_DEPTH, createComparisonSnapshot } from '../../domain/shogi/evaluationPresetComparison';
import { runEvaluationPresetComparisonInWorker } from '../../application/evaluationPresetComparisonWorkerClient';
import { isSameComparisonPosition, validateEvaluationPresetComparison } from '../../application/evaluationPresetComparisonValidation';
import { EvaluationPresetComparisonPanel, type EvaluationPresetComparisonDisplay } from './EvaluationPresetComparisonPanel';
import { formatLegalActionNotation, validateAndFormatPrincipalVariation } from '../../application/searchPrincipalVariation';
import { DEFAULT_SEARCH_EVALUATION_PRESET_ID, SEARCH_EVALUATION_PRESET_IDS, isSearchEvaluationPresetId, resolveSearchEvaluationPreset, type SearchEvaluationPresetId } from '../../domain/shogi/searchEvaluationPresets';
import type {
  PresetTimeLimitedSearchResult,
  TimeLimitedSearchQuiescenceMaxTacticalDepth,
} from '../../workers/timeLimitedIterativeDeepeningAlphaBetaWorkerProtocol';
import { SEARCH_EVALUATION_PRESET_DISPLAY } from './searchEvaluationPresetDisplay';
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { adjudicateNoLegalActions } from '../../domain/shogi/adjudication';
import { createInitialBoardState, BoardState, BoardSquare, Piece, PieceType } from '../../types/shogi';
import {
  executeDrop,
  evaluateAgreedJishogi,
  evaluateEnteringKingDeclaration,
  executeEnteringKingDeclaration,
  executeMove,
  proposeAgreedJishogi,
  respondToAgreedJishogiProposal,
  executeResignation,
  createShogiGameRecordFilename,
  createKifFileName,
  createKifText,
  downloadShogiGameRecord,
  downloadKifText,
  getLegalDropSquares,
  getMoveCandidates,
  getPromotionStatus,
  getPositionSnapshot,
  addGameRecordSessionBranch,
  createGameRecordSession,
  discardGameRecordSession,
  storeGameRecordSessionState,
  switchGameRecordSessionToBranch,
  switchGameRecordSessionToMainline,
  normalizePositionSnapshots,
  serializeShogiGameRecordSessionV1,
  importShogiGameRecordSession,
  importKifBytes,
  analyzeTwoPlyMinimaxSearch,
  cloneBoardState,
  executeLegalAction,
  getLegalActions,
  areLegalActionsEqual,
  MAX_SHOGI_GAME_RECORD_SESSION_FILE_BYTES,
  MAX_KIF_FILE_BYTES,
  PromotionStatus,
  type ShogiGameRecordSessionImportResult,
  type KifImportResult,
  type AgreedJishogiProposal,
  type GameRecordSession,
} from '../../domain/shogi';
import {
  runTimeLimitedIterativeDeepeningAlphaBetaSearchInWorker,
  TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerAbortError,
} from '../../application/timeLimitedIterativeDeepeningAlphaBetaWorkerClient';
import { ShogiTable } from './ShogiTable';
import { PromotionDialog } from './PromotionDialog';
import { ResignationDialog } from './ResignationDialog';
import { EnteringKingDeclarationDialog } from './EnteringKingDeclarationDialog';
import { AgreedJishogiDialog } from './AgreedJishogiDialog';
import { NewGameDialog } from './NewGameDialog';
import { MoveHistoryPanel } from './MoveHistoryPanel';
import { getGameResultDisplay } from './gameResultDisplay';
import { GameRecordImportDialog } from './GameRecordImportDialog';
import { KifImportDialog } from './KifImportDialog';
import { BranchReplayDialog } from './BranchReplayDialog';
import { AiSearchResultPanel, type AiSearchDisplay } from './AiSearchResultPanel';
import { AiJudgmentPanel } from './AiJudgmentPanel';

interface ShogiResearchScreenProps {
  initialState?: BoardState;
  timeLimitedQuiescenceComparisonRunner?: typeof runTimeLimitedQuiescenceComparisonInWorker;
  quiescenceComparisonRunner?: typeof runQuiescenceComparisonInWorker;
  comparisonRunner?: typeof runEvaluationPresetComparisonInWorker;
  workerSearchRunner?: TimeLimitedIterativeDeepeningAlphaBetaSearchRunner;
}

type TimeLimitedIterativeDeepeningAlphaBetaSearchRunner = (
  state: BoardState,
  maxDepth: number,
  timeLimitMilliseconds: number,
  signal?: AbortSignal,
  evaluationPresetId?: SearchEvaluationPresetId,
  quiescenceMaxTacticalDepth?: TimeLimitedSearchQuiescenceMaxTacticalDepth
) => Promise<PresetTimeLimitedSearchResult>;

interface PendingPromotion {
  from: { row: number; col: number };
  to: { row: number; col: number };
  status: Exclude<PromotionStatus, 'none'>;
}

interface PendingGameRecordImport {
  filename: string;
  session: GameRecordSession;
  state: BoardState;
  metadata: Extract<ShogiGameRecordSessionImportResult, { ok: true }>['metadata'];
}

interface PendingKifImport {
  filename: string;
  state: BoardState;
  metadata: Extract<KifImportResult, { ok: true }>['metadata'];
}

type WorkerSearchState =
  | { kind: 'idle' }
  | { kind: 'thinking' }
  | { kind: 'cancelled' }
  | { kind: 'error'; message: string };

interface ActiveWorkerSearch {
  kind: 'single' | 'comparison' | 'quiescence-comparison' | 'time-limited-quiescence-comparison';
  generation: number;
  controller: AbortController;
  state: BoardState;
}

type SelectionState =
  | { kind: 'none' }
  | { kind: 'board'; square: { row: number; col: number } }
  | { kind: 'hand'; pieceId: string; pieceType: PieceType };

const STATUS_BADGE_COLORS = {
  neutral: {
    bgColor: 'bg-stone-900/80 text-stone-300 border-stone-700/60',
    dotColor: 'bg-stone-500',
  },
  amber: {
    bgColor: 'bg-amber-950/80 text-amber-200 border-amber-700/60',
    dotColor: 'bg-amber-400',
  },
  sky: {
    bgColor: 'bg-sky-950/80 text-sky-200 border-sky-700/60',
    dotColor: 'bg-sky-400',
  },
  rose: {
    bgColor: 'bg-rose-950/80 text-rose-300 border-rose-800/60',
    dotColor: 'bg-rose-500',
  },
} as const;

const TIME_LIMITED_AI_MAX_DEPTH = 4;
const TIME_LIMITED_AI_TIME_LIMIT_MILLISECONDS = 1_000;
type QuiescenceSelection = TimeLimitedSearchQuiescenceMaxTacticalDepth | null;

export const ShogiResearchScreen: React.FC<ShogiResearchScreenProps> = ({
  initialState,
  timeLimitedQuiescenceComparisonRunner = runTimeLimitedQuiescenceComparisonInWorker,
  quiescenceComparisonRunner = runQuiescenceComparisonInWorker,
  comparisonRunner = runEvaluationPresetComparisonInWorker,
  workerSearchRunner = runTimeLimitedIterativeDeepeningAlphaBetaSearchInWorker,
}) => {
  const [boardState, setCurrentBoardState] = useState<BoardState>(() =>
    normalizePositionSnapshots(initialState ?? createInitialBoardState())
  );
  const [replayHistoryIndex, setReplayHistoryIndex] = useState<number | null>(null);
  const [gameRecordSession, setGameRecordSession] = useState<GameRecordSession | null>(null);
  const [pendingBranchHistoryIndex, setPendingBranchHistoryIndex] = useState<number | null>(null);
  const [isReturnToMainlineDialogOpen, setIsReturnToMainlineDialogOpen] = useState(false);
  const [selection, setSelection] = useState<SelectionState>({ kind: 'none' });
  const [pendingPromotion, setPendingPromotion] = useState<PendingPromotion | null>(null);
  const [isResignationDialogOpen, setIsResignationDialogOpen] = useState(false);
  const [isEnteringKingDialogOpen, setIsEnteringKingDialogOpen] = useState(false);
  const [isAgreedJishogiDialogOpen, setIsAgreedJishogiDialogOpen] = useState(false);
  const [isNewGameDialogOpen, setIsNewGameDialogOpen] = useState(false);
  const [pendingGameRecordImport, setPendingGameRecordImport] =
    useState<PendingGameRecordImport | null>(null);
  const [isGameRecordFileReading, setIsGameRecordFileReading] = useState(false);
  const [pendingKifImport, setPendingKifImport] = useState<PendingKifImport | null>(null);
  const [isKifFileReading, setIsKifFileReading] = useState(false);
  const [moveHistoryResetKey, setMoveHistoryResetKey] = useState(0);
  const [evaluationPresetId, setEvaluationPresetId] = useState<SearchEvaluationPresetId>(DEFAULT_SEARCH_EVALUATION_PRESET_ID);
  const [quiescenceSelection, setQuiescenceSelection] = useState<QuiescenceSelection>(null);
  const [aiSearchDisplay, setAiSearchDisplay] = useState<AiSearchDisplay | null>(null);
  const [timeLimitedQuiescenceComparisonState, setTimeLimitedQuiescenceComparisonState] = useState<WorkerSearchState>({ kind: 'idle' });
  const [timeLimitedQuiescenceComparisonDisplay, setTimeLimitedQuiescenceComparisonDisplay] = useState<TimeLimitedQuiescenceComparisonDisplay | null>(null);
  const [quiescenceComparisonState, setQuiescenceComparisonState] = useState<WorkerSearchState>({ kind: 'idle' });
  const [quiescenceComparisonDisplay, setQuiescenceComparisonDisplay] = useState<QuiescenceComparisonDisplay | null>(null);
  const [comparisonState, setComparisonState] = useState<WorkerSearchState>({ kind: 'idle' });
  const [comparisonDisplay, setComparisonDisplay] = useState<EvaluationPresetComparisonDisplay | null>(null);
  const [workerSearchState, setWorkerSearchState] = useState<WorkerSearchState>({ kind: 'idle' });
  const [agreedJishogiProposal, setAgreedJishogiProposal] = useState<AgreedJishogiProposal | null>(null);
  const [agreedJishogiError, setAgreedJishogiError] = useState<string | null>(null);
  const [exportNotice, setExportNotice] = useState<
    { kind: 'success' | 'error'; message: string } | null
  >(null);
  const [focusRequest, setFocusRequest] = useState<{
    row: number;
    col: number;
    requestId: number;
  } | null>(null);
  const focusRequestId = useRef(0);
  const resignationButtonRef = useRef<HTMLButtonElement>(null);
  const shouldRestoreResignationFocus = useRef(false);
  const enteringKingButtonRef = useRef<HTMLButtonElement>(null);
  const shouldRestoreEnteringKingFocus = useRef(false);
  const agreedJishogiButtonRef = useRef<HTMLButtonElement>(null);
  const shouldRestoreAgreedJishogiFocus = useRef(false);
  const newGameButtonRef = useRef<HTMLButtonElement>(null);
  const branchStartButtonRef = useRef<HTMLButtonElement>(null);
  const returnToMainlineButtonRef = useRef<HTMLButtonElement>(null);
  const shouldRestoreBranchStartFocus = useRef(false);
  const shouldRestoreMainlineFocus = useRef(false);
  const shouldRestoreNewGameFocus = useRef(false);
  const gameRecordImportButtonRef = useRef<HTMLButtonElement>(null);
  const gameRecordFileInputRef = useRef<HTMLInputElement>(null);
  const shouldRestoreGameRecordImportFocus = useRef(false);
  const kifImportButtonRef = useRef<HTMLButtonElement>(null);
  const kifFileInputRef = useRef<HTMLInputElement>(null);
  const shouldRestoreKifImportFocus = useRef(false);
  const activeWorkerSearchRef = useRef<ActiveWorkerSearch | null>(null);
  const workerSearchGenerationRef = useRef(0);

  const replaySnapshot =
    replayHistoryIndex === null
      ? null
      : getPositionSnapshot(boardState, replayHistoryIndex);
  const isViewingReplay = replaySnapshot !== null;
  const activeSessionBranch = (() => {
    if (!gameRecordSession || gameRecordSession.selection.kind !== 'branch') return null;
    const activeRecordId = gameRecordSession.selection.recordId;
    return gameRecordSession.branches.find((branch) => branch.state.recordId === activeRecordId) ?? null;
  })();
  const dialogsAreOpen =
    pendingPromotion !== null ||
    isResignationDialogOpen ||
    isEnteringKingDialogOpen ||
    isAgreedJishogiDialogOpen ||
    isNewGameDialogOpen ||
    pendingBranchHistoryIndex !== null ||
    isReturnToMainlineDialogOpen ||
    pendingGameRecordImport !== null ||
    isGameRecordFileReading ||
    pendingKifImport !== null ||
    isKifFileReading;
  const isEnded = boardState.status === 'ended';
  const isResignationAvailable = boardState.status === 'active' || boardState.status === 'check';
  const isEnteringKingAvailable = boardState.status === 'active' || boardState.status === 'check';
  const isNewGameAvailable = isEnteringKingAvailable || isEnded;
  const isTimeLimitedQuiescenceComparisonThinking = timeLimitedQuiescenceComparisonState.kind === 'thinking';
  const isQuiescenceComparisonThinking = quiescenceComparisonState.kind === 'thinking';
  const isComparisonThinking = comparisonState.kind === 'thinking';
  const isWorkerSearchThinking = workerSearchState.kind === 'thinking';
  const isInteractionBlocked = isEnded || isViewingReplay || dialogsAreOpen || isWorkerSearchThinking;
  const selectedSquare =
    !isEnded && !isViewingReplay && selection.kind === 'board' ? selection.square : null;
