  useEffect(() => {
    if (isReturnToMainlineDialogOpen || !shouldRestoreMainlineFocus.current) return;
    shouldRestoreMainlineFocus.current = false;
    returnToMainlineButtonRef.current?.focus();
  }, [isReturnToMainlineDialogOpen]);

  useEffect(() => {
