  const cancelEnteringKing = useCallback(() => {
    shouldRestoreEnteringKingFocus.current = true;
    setIsEnteringKingDialogOpen(false);
  }, []);

  const confirmEnteringKing = () => {
    const result = executeEnteringKingDeclaration(boardState, {
