  const openAgreedJishogiDialog = () => {
    if (
      !isEnteringKingAvailable ||
      isWorkerSearchThinking ||
      pendingPromotion ||
      isResignationDialogOpen ||
      isEnteringKingDialogOpen ||
      isAgreedJishogiDialogOpen ||
