  const confirmGameRecordImport = () => {
    if (!pendingGameRecordImport) return;
    shouldRestoreResignationFocus.current = false;
    shouldRestoreEnteringKingFocus.current = false;
    shouldRestoreAgreedJishogiFocus.current = false;
    shouldRestoreNewGameFocus.current = false;
    shouldRestoreGameRecordImportFocus.current = true;
    cancelActiveWorkerSearch();
    focusRequestId.current = 0;
    setBoardState(pendingGameRecordImport.state);
    setAiSearchDisplay(null);
    setWorkerSearchState({ kind: 'idle' });
    setGameRecordSession(pendingGameRecordImport.session);
    setReplayHistoryIndex(null);
    setSelection({ kind: 'none' });
    setPendingPromotion(null);
    setIsResignationDialogOpen(false);
    setIsEnteringKingDialogOpen(false);
    setIsAgreedJishogiDialogOpen(false);
    setIsNewGameDialogOpen(false);
    setAgreedJishogiProposal(null);
    setAgreedJishogiError(null);
    setFocusRequest(null);
    setMoveHistoryResetKey((current) => current + 1);
    setExportNotice({
      kind: 'success',
      message: `対局記録を読み込みました（${pendingGameRecordImport.filename}）`,
    });
    setPendingGameRecordImport(null);
  };

  const compareEvaluationPresets = async () => {
    if (isInteractionBlocked || activeWorkerSearchRef.current) return;
    invalidateComparison();
    const snapshot = createComparisonSnapshot(boardState);
    const generation = ++workerSearchGenerationRef.current;
    const controller = new AbortController();
    const job: ActiveWorkerSearch = { kind: 'comparison', generation, controller, state: boardState };
    activeWorkerSearchRef.current = job;
    setComparisonState({ kind: 'thinking' });
    const isCurrent = () => activeWorkerSearchRef.current === job &&
      workerSearchGenerationRef.current === generation && !controller.signal.aborted;
    try {
      const results = await comparisonRunner(snapshot, EVALUATION_PRESET_COMPARISON_DEPTH, controller.signal);
      if (!isCurrent()) return;
      if (!isSameComparisonPosition(snapshot, job.state)) throw new Error('比較の開始局面が変更されました。');
      validateEvaluationPresetComparison(snapshot, EVALUATION_PRESET_COMPARISON_DEPTH, results);
      const entries = results.map((result) => ({ result,
        principalVariationNotations: result.selectedAction
          ? validateAndFormatPrincipalVariation(snapshot, result, result.depth)! : [],
      }));
      activeWorkerSearchRef.current = null;
      setComparisonDisplay({ perspective: snapshot.turn, entries });
      setComparisonState({ kind: 'idle' });
    } catch (error) {
      if (!isCurrent()) return;
      activeWorkerSearchRef.current = null;
      setComparisonDisplay(null);
      setComparisonState(error instanceof Error && error.name === 'AbortError'
        ? { kind: 'cancelled' }
        : { kind: 'error', message: error instanceof Error ? error.message : '比較に失敗しました。' });
    }
  };

  const compareQuiescenceSettings = async () => {
    if (isInteractionBlocked || activeWorkerSearchRef.current) return;
    invalidateQuiescenceComparison();
    const snapshot = createComparisonSnapshot(boardState);
    const generation = ++workerSearchGenerationRef.current;
    const controller = new AbortController();
    const job: ActiveWorkerSearch = { kind: 'quiescence-comparison', generation, controller, state: boardState };
    activeWorkerSearchRef.current = job;
    setQuiescenceComparisonState({ kind: 'thinking' });
    const isCurrent = () => activeWorkerSearchRef.current === job &&
      workerSearchGenerationRef.current === generation && !controller.signal.aborted;
    try {
      const results = await quiescenceComparisonRunner(snapshot, QUIESCENCE_COMPARISON_DEPTH, controller.signal);
      if (!isCurrent()) return;
      if (!isSameComparisonPosition(snapshot, job.state)) throw new Error('比較の開始局面が変更されました。');
      validateQuiescenceComparison(snapshot, QUIESCENCE_COMPARISON_DEPTH, results);
      const entries = results.map((result) => ({ result,
        principalVariationNotations: result.selectedAction
          ? validateAndFormatPrincipalVariation(snapshot, result, result.depth + (result.quiescenceMaxTacticalDepth ?? 0))! : [],
      }));
      activeWorkerSearchRef.current = null;
      setQuiescenceComparisonDisplay({ perspective: snapshot.turn, entries });
      setQuiescenceComparisonState({ kind: 'idle' });
    } catch (error) {
      if (!isCurrent()) return;
      activeWorkerSearchRef.current = null;
      setQuiescenceComparisonDisplay(null);
      setQuiescenceComparisonState(error instanceof Error && error.name === 'AbortError'
        ? { kind: 'cancelled' }
        : { kind: 'error', message: error instanceof Error ? error.message : '比較に失敗しました。' });
    }
  };

  const compareTimeLimitedQuiescenceSettings = async () => {
    if (isInteractionBlocked || activeWorkerSearchRef.current) return;
    invalidateTimeLimitedQuiescenceComparison();
    const snapshot = createComparisonSnapshot(boardState);
    const generation = ++workerSearchGenerationRef.current;
    const controller = new AbortController();
    const job: ActiveWorkerSearch = { kind: 'time-limited-quiescence-comparison', generation, controller, state: boardState };
    activeWorkerSearchRef.current = job;
    setTimeLimitedQuiescenceComparisonState({ kind: 'thinking' });
    const isCurrent = () => activeWorkerSearchRef.current === job &&
      workerSearchGenerationRef.current === generation && !controller.signal.aborted;
    try {
      const results = await timeLimitedQuiescenceComparisonRunner(snapshot, TIME_LIMITED_QUIESCENCE_COMPARISON_MAX_DEPTH, TIME_LIMITED_QUIESCENCE_COMPARISON_MILLISECONDS, controller.signal);
      if (!isCurrent()) return;
      if (!isSameComparisonPosition(snapshot, job.state)) throw new Error('比較の開始局面が変更されました。');
      validateTimeLimitedQuiescenceComparison(snapshot, TIME_LIMITED_QUIESCENCE_COMPARISON_MAX_DEPTH, TIME_LIMITED_QUIESCENCE_COMPARISON_MILLISECONDS, results);
      const entries = results.map((result) => ({ result,
        principalVariationNotations: result.resultSource === 'fallback'
          ? result.selectedAction ? [formatLegalActionNotation(snapshot, result.selectedAction)] : []
          : result.selectedAction
            ? validateAndFormatPrincipalVariation(snapshot, result, (result.resultSource === 'partial-root' ? 1 : result.depth) + (result.quiescenceMaxTacticalDepth ?? 0))! : [],
      }));
      activeWorkerSearchRef.current = null;
      setTimeLimitedQuiescenceComparisonDisplay({ perspective: snapshot.turn, entries });
      setTimeLimitedQuiescenceComparisonState({ kind: 'idle' });
    } catch (error) {
      if (!isCurrent()) return;
      activeWorkerSearchRef.current = null;
      setTimeLimitedQuiescenceComparisonDisplay(null);
      setTimeLimitedQuiescenceComparisonState(error instanceof Error && error.name === 'AbortError'
        ? { kind: 'cancelled' }
        : { kind: 'error', message: error instanceof Error ? error.message : '比較に失敗しました。' });
    }
  };

  const makeTwoPlyAiMove = () => {
    if (isInteractionBlocked || isComparisonThinking || isQuiescenceComparisonThinking || isTimeLimitedQuiescenceComparisonThinking || activeWorkerSearchRef.current) return;
    invalidateComparison();

    const result = {
      ...analyzeTwoPlyMinimaxSearch(boardState, resolveSearchEvaluationPreset(evaluationPresetId)),
      evaluationPresetId,
    };
    if (!result.selectedAction) {
      const ended = adjudicateNoLegalActions(boardState);
      if (ended !== null) {
        setBoardState(ended);
        setSelection({ kind: 'none' });
        setPendingPromotion(null);
      }
      return;
    }

    const selectedNotation = formatLegalActionNotation(boardState, result.selectedAction);
    const candidateNotations = result.topCandidates.map((candidate) =>
      formatLegalActionNotation(boardState, candidate.action)
    );
    const execution = executeLegalAction(boardState, result.selectedAction, { proposer: 'local_ai' });
    if (execution.type !== 'applied') {
      throw new Error('A selected legal AI action could not be executed.');
    }

    setBoardState(execution.state);
    setSelection({ kind: 'none' });
    setPendingPromotion(null);
    setAiSearchDisplay({ kind: 'two-ply', perspective: boardState.turn, result, selectedNotation, candidateNotations });
  };

  const makeTimeLimitedAiMove = () => {
    if (isInteractionBlocked || activeWorkerSearchRef.current) return;
    invalidateComparison();

    const controller = new AbortController();
    const generation = workerSearchGenerationRef.current + 1;
    const searchState = boardState;
    const searchPresetId = evaluationPresetId;
    const searchQuiescenceMaxTacticalDepth = quiescenceSelection;
    workerSearchGenerationRef.current = generation;
    activeWorkerSearchRef.current = { kind: 'single', generation, controller, state: searchState };
    setSelection({ kind: 'none' });
    setPendingPromotion(null);
    setAiSearchDisplay(null);
    setWorkerSearchState({ kind: 'thinking' });

    const isCurrentSearch = (): boolean => {
      const activeSearch = activeWorkerSearchRef.current;
      return activeSearch?.generation === generation && !activeSearch.controller.signal.aborted;
    };

    const pendingSearch = searchQuiescenceMaxTacticalDepth === null
      ? workerSearchRunner(
        searchState,
        TIME_LIMITED_AI_MAX_DEPTH,
        TIME_LIMITED_AI_TIME_LIMIT_MILLISECONDS,
        controller.signal,
        searchPresetId
      )
      : workerSearchRunner(
        searchState,
        TIME_LIMITED_AI_MAX_DEPTH,
        TIME_LIMITED_AI_TIME_LIMIT_MILLISECONDS,
        controller.signal,
        searchPresetId,
        searchQuiescenceMaxTacticalDepth
      );

    void pendingSearch.then(
      (result) => {
        if (!isCurrentSearch()) return;

        if (result.evaluationPresetId !== searchPresetId) {
          activeWorkerSearchRef.current = null;
          setWorkerSearchState({ kind: 'error', message: 'AIの評価設定が探索要求と一致しません。' });
          return;
        }
        if (result.quiescenceMaxTacticalDepth !== searchQuiescenceMaxTacticalDepth) {
          activeWorkerSearchRef.current = null;
          setWorkerSearchState({ kind: 'error', message: 'AIの静止探索設定が探索要求と一致しません。' });
          return;
        }

        if (!result.selectedAction) {
          activeWorkerSearchRef.current = null;
          if (result.resultSource === 'no-legal-actions' && result.rootLegalActionCount === 0 && !result.timedOut) {
            const ended = adjudicateNoLegalActions(searchState);
            if (ended !== null) {
              setBoardState(ended);
              setWorkerSearchState({ kind: 'idle' });
              return;
            }
          }
          setWorkerSearchState({
            kind: 'error',
            message: 'AIの指し手を受け取れませんでした。',
          });
          return;
        }

        // Preserve the established selected-action failure boundary before the
        // additional multi-ply result is trusted or shown.
        const selectedActionCheck = executeLegalAction(
          cloneBoardState(searchState),
          result.selectedAction,
          { proposer: 'local_ai' }
        );
        if (selectedActionCheck.type !== 'applied') {
          activeWorkerSearchRef.current = null;
          setWorkerSearchState({
            kind: 'error',
            message: 'AIの指し手を適用できませんでした。',
          });
          return;
        }

        const rootActions = result.resultSource === 'fallback' ? getLegalActions(searchState) : null;
        const fallbackValid = rootActions !== null && result.completedDepth === 0 && result.depth === 0 &&
          result.iterations.length === 0 && result.rootLegalActionCount === rootActions.length &&
          result.selectedEvaluation === null && result.evaluationBreakdown === null &&
          result.principalVariation.length === 0 && result.timedOut &&
          rootActions[0] !== undefined && areLegalActionsEqual(rootActions[0], result.selectedAction);
        const principalVariationNotations = result.resultSource === 'fallback'
          ? fallbackValid ? [] : null
          : result.resultSource === 'partial-root'
            ? validatePartialRoot(searchState, result, result.quiescenceMaxTacticalDepth ?? 0)
            : validateAndFormatPrincipalVariation(searchState, result, result.completedDepth + (result.quiescenceMaxTacticalDepth ?? 0));
        if (!principalVariationNotations) {
          activeWorkerSearchRef.current = null;
          setWorkerSearchState({
            kind: 'error',
            message: 'AIの読み筋を検証できませんでした。',
          });
          return;
        }

        const execution = executeLegalAction(searchState, result.selectedAction, {
          proposer: 'local_ai',
        });

        if (!isCurrentSearch()) return;
        activeWorkerSearchRef.current = null;
        if (execution.type !== 'applied') {
          setWorkerSearchState({
            kind: 'error',
            message: 'AIの指し手を適用できませんでした。',
          });
          return;
        }

        const selectedNotation = result.resultSource === 'fallback'
          ? formatLegalActionNotation(searchState, result.selectedAction)
          : principalVariationNotations[0];
        setBoardState(execution.state);
        setSelection({ kind: 'none' });
        setPendingPromotion(null);
        setAiSearchDisplay({
          kind: 'time-limited-worker', perspective: searchState.turn, result, selectedNotation, principalVariationNotations,
        });
        setWorkerSearchState({ kind: 'idle' });
      },
      (error: unknown) => {
        if (!isCurrentSearch()) return;

        activeWorkerSearchRef.current = null;
        if (
          error instanceof TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerAbortError ||
          (error instanceof Error && error.name === 'AbortError')
        ) {
          setWorkerSearchState({ kind: 'cancelled' });
          return;
        }

        setWorkerSearchState({
          kind: 'error',
          message: error instanceof Error ? error.message : '時間制限AIの探索に失敗しました。',
        });
      }
    );
  };

  const handleSquareClick = (square: BoardSquare) => {
    if (isInteractionBlocked) return;
    if (selection.kind === 'hand') {
      if (square.piece?.player === boardState.turn) {
        setSelection({ kind: 'board', square: { row: square.row, col: square.col } });
        return;
      }

      const isDropCandidate = candidateSquares.some(
        (candidate) => candidate.row === square.row && candidate.col === square.col
      );
      if (!isDropCandidate) return;

      const result = executeDrop(
        boardState,
        selection.pieceId,
        { row: square.row, col: square.col },
        { mode: 'assist', proposer: 'human' }
      );
      if (result.type === 'applied') {
        setBoardState(result.state);
        setAiSearchDisplay(null);
        setSelection({ kind: 'none' });
        restoreBoardFocus({ row: square.row, col: square.col });
      }
      return;
    }

    // Case 1: No square currently selected
    if (!selectedSquare) {
      if (square.piece && square.piece.player === boardState.turn) {
        setSelection({ kind: 'board', square: { row: square.row, col: square.col } });
      }
      return;
    }

    // Case 2: Clicked on already selected square -> Deselect
    if (selectedSquare.row === square.row && selectedSquare.col === square.col) {
      setSelection({ kind: 'none' });
      return;
    }

    // Case 3: Clicked on another own piece -> Switch selection
    if (square.piece && square.piece.player === boardState.turn) {
      setSelection({ kind: 'board', square: { row: square.row, col: square.col } });
      return;
    }

    // Case 4: Clicked on a legal move candidate square -> Execute move
    const isCandidate = candidateSquares.some(
      (c) => c.row === square.row && c.col === square.col
    );

    if (isCandidate) {
      const from = selectedSquare;
      const to = { row: square.row, col: square.col };
      const movingPiece = boardState.squares[from.row][from.col].piece;
      if (!movingPiece) return;
      const promotionStatus = getPromotionStatus(movingPiece, from, to);

      if (promotionStatus !== 'none') {
        invalidateComparison();
        setPendingPromotion({ from, to, status: promotionStatus });
        return;
      }

      const result = executeMove(boardState, from, to, {
        mode: 'assist',
        proposer: 'human',
      });
      if (result.type === 'applied') {
        setBoardState(result.state);
        setAiSearchDisplay(null);
      }
      setSelection({ kind: 'none' });
      return;
    }

    // Case 5: Clicked on an invalid square (opponent piece, empty non-candidate, etc.) -> Do nothing
  };

  const handleHandPieceSelect = (piece: Piece) => {
    if (isInteractionBlocked || piece.player !== boardState.turn) {
      return;
    }
    setSelection((current) =>
      current.kind === 'hand' && current.pieceId === piece.id
        ? { kind: 'none' }
        : { kind: 'hand', pieceId: piece.id, pieceType: piece.type }
    );
  };

  const handleScreenKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (dialogsAreOpen) return;
    if (event.key === 'Escape' && selection.kind === 'hand') {
      event.preventDefault();
      setSelection({ kind: 'none' });
    }
  };

  const displayedTurn = replaySnapshot?.turn ?? boardState.turn;
  const turnLabel = displayedTurn === 'sente' ? '先手番' : '後手番';

  const statusBadgeInfo = useMemo(() => {
    if (replaySnapshot) {
      const positionLabel =
        replaySnapshot.historyIndex === 0
          ? '初期局面を閲覧中'
          : `${replaySnapshot.historyIndex}手目終了局面を閲覧中`;
      return {
        text: `${positionLabel} / 次は${turnLabel}${replaySnapshot.status === 'check' ? ' / 王手' : ''}`,
        isLive: false,
        bgColor: 'bg-sky-950/80 text-sky-200 border-sky-700/60',
        dotColor: 'bg-sky-400',
      };
    }

    if (boardState.status === 'ended' && boardState.result) {
      const display = getGameResultDisplay(boardState.result);
      return {
        text: `終局 / ${display.statusText}`,
        isLive: false,
        ...STATUS_BADGE_COLORS[display.tone],
      };
    }

    if (boardState.status === 'check') {
      return {
        text: `王手 / ${turnLabel}`,
        isLive: true,
        bgColor: 'bg-rose-950/70 text-rose-300 border-rose-800/50',
        dotColor: 'bg-rose-400',
      };
    }

    return {
      text: `対局中 / ${turnLabel}`,
      isLive: true,
      bgColor: 'bg-amber-950/70 text-amber-300 border-amber-800/50',
      dotColor: 'bg-amber-400',
    };
  }, [boardState.status, boardState.result, replaySnapshot, turnLabel]);

  return (
    <div
      id="shogi-research-screen"
      data-turn={boardState.turn}
      data-move-number={boardState.moveNumber}
      data-history-count={boardState.history.length}
      data-foul-history-count={boardState.foulHistory?.length ?? 0}
      data-position-history-count={boardState.positionHistory?.length ?? 0}
      data-sente-hand-count={boardState.senteHand.length}
      data-gote-hand-count={boardState.goteHand.length}
      data-last-move={boardState.lastMove?.notation ?? ''}
      data-result={boardState.result?.endReason ?? ''}
      data-move-limit-jishogi={boardState.moveLimitJishogi?.kind ?? ''}
      data-position-snapshot-count={boardState.positionSnapshots?.length ?? 0}
      data-replay-history-index={replayHistoryIndex ?? ''}
      data-branch-origin-history-index={activeSessionBranch?.originHistoryIndex ?? ''}
      data-session-branch-count={gameRecordSession?.branches.length ?? 0}
      data-active-session-record={
        activeSessionBranch?.state.recordId ?? (boardState.branchFrom ? 'standalone-branch' : 'mainline')
      }
      data-ai-search-kind={aiSearchDisplay?.kind ?? ''}
      data-ai-search-depth={
        aiSearchDisplay?.kind === 'time-limited-worker'
          ? aiSearchDisplay.result.completedDepth
          : aiSearchDisplay?.result.depth ?? ''
      }
      data-ai-search-visited-position-count={aiSearchDisplay?.result.visitedPositionCount ?? ''}
      data-worker-search-state={workerSearchState.kind}
      onKeyDown={handleScreenKeyDown}
      className="min-h-full w-full flex flex-col items-center justify-between py-6 px-3 sm:px-6 bg-[#0f1115] text-stone-200"
    >
      {/* Top Header Section */}
      <header className="w-full max-w-4xl flex flex-col items-center text-center gap-2 mb-6">
        <div className="flex items-center gap-3">
          <h1
            id="shogi-screen-title"
            className="text-2xl sm:text-3xl font-serif font-bold text-amber-100 tracking-wider"
            style={{
              fontFamily:
                '"Yu Mincho", "Hiragino Mincho ProN", "YuMincho", "MS PMincho", "Noto Serif JP", serif',
            }}
          >
            将棋研究
          </h1>
          <span
            id="shogi-status-badge"
            className={`inline-flex items-center gap-1.5 px-3 py-0.5 rounded-full text-xs font-medium ${statusBadgeInfo.bgColor} border shadow-inner`}
            role="status"
            aria-live="polite"
          >
            <span
              className={`w-1.5 h-1.5 rounded-full ${statusBadgeInfo.dotColor} ${statusBadgeInfo.isLive ? 'animate-pulse' : ''}`}
            />
            {statusBadgeInfo.text}
          </span>
        </div>

        <p
          id="shogi-screen-description"
          className="text-xs sm:text-sm text-stone-400 font-sans tracking-wide max-w-xl"
        >
          AIとの対局・棋譜・判断ログを記録する研究画面です。
        </p>
        <div className="mt-2 w-full min-w-0 max-w-sm space-y-1 text-xs text-stone-300">
          <label htmlFor="evaluation-preset" className="block">評価プリセット</label>
          <select
            id="evaluation-preset"
            aria-describedby="evaluation-preset-description"
            value={evaluationPresetId}
            disabled={isWorkerSearchThinking || isComparisonThinking || isQuiescenceComparisonThinking || isTimeLimitedQuiescenceComparisonThinking || dialogsAreOpen}
            onChange={(event) => {
              if (!activeWorkerSearchRef.current && isSearchEvaluationPresetId(event.target.value)) {
                setEvaluationPresetId(event.target.value);
              }
            }}
            className="w-full min-w-0 rounded border border-stone-700 bg-stone-900 px-3 py-2 text-sm text-stone-100 disabled:opacity-50"
          >
            {SEARCH_EVALUATION_PRESET_IDS.map((id) => (
              <option key={id} value={id}>{SEARCH_EVALUATION_PRESET_DISPLAY[id].name}</option>
            ))}
          </select>
          <p id="evaluation-preset-description">{SEARCH_EVALUATION_PRESET_DISPLAY[evaluationPresetId].description}</p>
        </div>
        <div className="mt-2 w-full min-w-0 max-w-sm space-y-1 text-xs text-stone-300">
          <label htmlFor="quiescence-selection" className="block">静止探索（駒取りの読み足し）</label>
          <select
            id="quiescence-selection"
            aria-describedby="quiescence-selection-description"
            value={quiescenceSelection === null ? 'disabled' : String(quiescenceSelection)}
            disabled={isWorkerSearchThinking || isComparisonThinking || isQuiescenceComparisonThinking || isTimeLimitedQuiescenceComparisonThinking || dialogsAreOpen}
            onChange={(event) => {
              if (activeWorkerSearchRef.current) return;
              const value = event.target.value;
              const nextSelection: QuiescenceSelection = value === '1' ? 1 : value === '2' ? 2 : null;
              if (value !== 'disabled' && nextSelection === null) return;
              setQuiescenceSelection(nextSelection);
              setAiSearchDisplay(null);
            }}
            className="w-full min-w-0 rounded border border-stone-700 bg-stone-900 px-3 py-2 text-sm text-stone-100 disabled:opacity-50"
          >
            <option value="disabled">無効</option>
            <option value="1">追加1手</option>
            <option value="2">追加2手</option>
          </select>
          <p id="quiescence-selection-description">通常探索の葉で駒取りだけを追加で読みます。</p>
        </div>
        <div className="mt-2 flex max-w-full flex-wrap justify-center gap-2">
          <button
            type="button"
            onClick={makeTwoPlyAiMove}
            disabled={isInteractionBlocked || isComparisonThinking || isQuiescenceComparisonThinking || isTimeLimitedQuiescenceComparisonThinking}
            className="rounded border border-violet-700/70 bg-violet-950/45 px-4 py-1.5 font-serif text-sm tracking-[0.1em] text-violet-100 shadow-inner outline-none transition hover:border-violet-500 hover:bg-violet-900/55 focus-visible:ring-2 focus-visible:ring-amber-300 disabled:cursor-not-allowed disabled:border-stone-800 disabled:text-stone-600 disabled:opacity-65"
          >
            2手読みAIに指させる
          </button>
          <button
            type="button"
            onClick={makeTimeLimitedAiMove}
            disabled={isInteractionBlocked || activeWorkerSearchRef.current !== null}
            className="rounded border border-sky-700/70 bg-sky-950/45 px-4 py-1.5 font-serif text-sm tracking-[0.1em] text-sky-100 shadow-inner outline-none transition hover:border-sky-500 hover:bg-sky-900/55 focus-visible:ring-2 focus-visible:ring-amber-300 disabled:cursor-not-allowed disabled:border-stone-800 disabled:text-stone-600 disabled:opacity-65"
          >
            時間制限AIに指させる
          </button>
          <button type="button" onClick={compareEvaluationPresets}
            disabled={isInteractionBlocked || isComparisonThinking || isQuiescenceComparisonThinking || isTimeLimitedQuiescenceComparisonThinking}
            className="rounded border border-sky-700/70 bg-sky-950/45 px-4 py-1.5 font-serif text-sm text-sky-100 disabled:opacity-50">
            3プリセットを比較
          </button>
          <button type="button" onClick={compareQuiescenceSettings}
            disabled={isInteractionBlocked || isComparisonThinking || isQuiescenceComparisonThinking || isTimeLimitedQuiescenceComparisonThinking}
            className="max-w-full rounded border border-sky-700/70 bg-sky-950/45 px-4 py-1.5 font-serif text-sm text-sky-100 disabled:opacity-50">
            静止探索を固定深さ3で比較
          </button>
          <button type="button" onClick={compareTimeLimitedQuiescenceSettings}
            disabled={isInteractionBlocked || activeWorkerSearchRef.current !== null}
            className="max-w-full rounded border border-sky-700/70 bg-sky-950/45 px-4 py-1.5 font-serif text-sm text-sky-100 disabled:opacity-50">
            静止探索を同じ1秒で比較
          </button>
          {isTimeLimitedQuiescenceComparisonThinking && (
            <button type="button" onClick={() => {
              invalidateTimeLimitedQuiescenceComparison();
              setTimeLimitedQuiescenceComparisonState({ kind: 'cancelled' });
            }} className="max-w-full rounded border border-rose-800/70 px-4 py-1.5 text-sm text-rose-100">
              同一時間の静止探索比較を中止
            </button>
          )}
          {isQuiescenceComparisonThinking && (
            <button type="button" onClick={() => {
              invalidateQuiescenceComparison();
              setQuiescenceComparisonState({ kind: 'cancelled' });
            }} className="max-w-full rounded border border-rose-800/70 px-4 py-1.5 text-sm text-rose-100">
              静止探索比較を中止
            </button>
          )}
          {isComparisonThinking && (
            <button type="button" onClick={() => {
              invalidateComparison();
              setComparisonState({ kind: 'cancelled' });
            }} className="rounded border border-rose-800/70 px-4 py-1.5 text-sm text-rose-100">
              比較を中止
            </button>
          )}
          {isWorkerSearchThinking && (
            <button
              type="button"
              onClick={cancelActiveWorkerSearch}
              className="rounded border border-rose-800/70 bg-rose-950/45 px-4 py-1.5 font-serif text-sm tracking-[0.1em] text-rose-100 shadow-inner outline-none transition hover:border-rose-600 hover:bg-rose-900/55 focus-visible:ring-2 focus-visible:ring-amber-300"
            >
              思考を中止
            </button>
          )}
          {activeSessionBranch && (
            <button
              ref={returnToMainlineButtonRef}
              type="button"
              onClick={openReturnToMainlineDialog}
              disabled={dialogsAreOpen}
              aria-haspopup="dialog"
              aria-expanded={isReturnToMainlineDialogOpen}
              className="rounded border border-sky-700/70 bg-sky-950/45 px-4 py-1.5 font-serif text-sm tracking-[0.1em] text-sky-100 shadow-inner outline-none transition hover:border-sky-500 hover:bg-sky-900/55 focus-visible:ring-2 focus-visible:ring-amber-300 disabled:cursor-not-allowed disabled:opacity-65"
            >
              本譜へ戻る
            </button>
          )}
          <button
            ref={enteringKingButtonRef}
            type="button"
            onClick={openEnteringKingDialog}
            disabled={!isEnteringKingAvailable || isViewingReplay || dialogsAreOpen || isWorkerSearchThinking}
            aria-haspopup="dialog"
            aria-expanded={isEnteringKingDialogOpen}
            className="rounded border border-amber-700/70 bg-amber-950/45 px-4 py-1.5 font-serif text-sm tracking-[0.12em] text-amber-100 shadow-inner outline-none transition hover:border-amber-500 hover:bg-amber-900/55 focus-visible:ring-2 focus-visible:ring-amber-300 disabled:cursor-not-allowed disabled:border-stone-800 disabled:text-stone-600 disabled:opacity-65"
          >
            入玉宣言
          </button>
          <button
            ref={agreedJishogiButtonRef}
            type="button"
            onClick={openAgreedJishogiDialog}
            disabled={!isEnteringKingAvailable || isViewingReplay || dialogsAreOpen || isWorkerSearchThinking}
            aria-haspopup="dialog"
            aria-expanded={isAgreedJishogiDialogOpen}
            className="rounded border border-sky-800/70 bg-sky-950/45 px-4 py-1.5 font-serif text-sm tracking-[0.1em] text-sky-100 shadow-inner outline-none transition hover:border-sky-600 hover:bg-sky-900/55 focus-visible:ring-2 focus-visible:ring-amber-300 disabled:cursor-not-allowed disabled:border-stone-800 disabled:text-stone-600 disabled:opacity-65"
          >
            持将棋を提案
          </button>
          <button
            ref={resignationButtonRef}
            type="button"
            onClick={openResignationDialog}
            disabled={!isResignationAvailable || isViewingReplay || dialogsAreOpen || isWorkerSearchThinking}
            aria-haspopup="dialog"
            aria-expanded={isResignationDialogOpen}
            className="rounded border border-rose-900/70 bg-stone-900/80 px-4 py-1.5 font-serif text-sm tracking-[0.14em] text-rose-200 shadow-inner outline-none transition hover:border-rose-700 hover:bg-rose-950/55 focus-visible:ring-2 focus-visible:ring-amber-300 disabled:cursor-not-allowed disabled:border-stone-800 disabled:text-stone-600 disabled:opacity-65"
          >
            投了
          </button>
          <button
            type="button"
            onClick={saveGameRecord}
            disabled={dialogsAreOpen}
            className="rounded border border-violet-800/70 bg-violet-950/45 px-4 py-1.5 font-serif text-sm tracking-[0.1em] text-violet-100 shadow-inner outline-none transition hover:border-violet-600 hover:bg-violet-900/55 focus-visible:ring-2 focus-visible:ring-amber-300 disabled:cursor-not-allowed disabled:border-stone-800 disabled:text-stone-600 disabled:opacity-65"
          >
              対局記録を保存
            </button>
            <button
              type="button"
              onClick={saveKifRecord}
              disabled={dialogsAreOpen}
              className="rounded-md border border-amber-400 bg-amber-50 px-3 py-2 text-sm font-semibold text-amber-900 transition hover:bg-amber-100 disabled:cursor-not-allowed disabled:opacity-50"
            >
              KIF棋譜を保存
            </button>
          <input
            ref={kifFileInputRef}
            id="shogi-kif-file-input"
            type="file"
            accept=".kif,text/plain"
            className="sr-only"
            tabIndex={-1}
            aria-labelledby="shogi-kif-import-button"
            onChange={handleKifFileChange}
          />
          <button
            ref={kifImportButtonRef}
            id="shogi-kif-import-button"
            type="button"
            onClick={selectKifFile}
            disabled={dialogsAreOpen || isKifFileReading}
            aria-controls="shogi-kif-file-input"
            aria-haspopup="dialog"
            aria-expanded={pendingKifImport !== null}
            className="rounded border border-amber-700/70 bg-amber-950/45 px-4 py-1.5 font-serif text-sm tracking-[0.1em] text-amber-100 shadow-inner outline-none transition hover:border-amber-500 hover:bg-amber-900/55 focus-visible:ring-2 focus-visible:ring-amber-300 disabled:cursor-not-allowed disabled:border-stone-800 disabled:text-stone-600 disabled:opacity-65"
          >
            {isKifFileReading ? 'KIF棋譜を検証中' : 'KIF棋譜を読み込む'}
          </button>
          <input
            ref={gameRecordFileInputRef}
            id="shogi-game-record-file-input"
            type="file"
            accept=".json,application/json"
            className="sr-only"
            tabIndex={-1}
            aria-labelledby="shogi-game-record-import-button"
            onChange={handleGameRecordFileChange}
          />
          <button
            ref={gameRecordImportButtonRef}
            id="shogi-game-record-import-button"
            type="button"
            onClick={selectGameRecordFile}
            disabled={dialogsAreOpen || isGameRecordFileReading}
            aria-controls="shogi-game-record-file-input"
            aria-haspopup="dialog"
            aria-expanded={pendingGameRecordImport !== null}
            className="rounded border border-violet-800/70 bg-violet-950/45 px-4 py-1.5 font-serif text-sm tracking-[0.1em] text-violet-100 shadow-inner outline-none transition hover:border-violet-600 hover:bg-violet-900/55 focus-visible:ring-2 focus-visible:ring-amber-300 disabled:cursor-not-allowed disabled:border-stone-800 disabled:text-stone-600 disabled:opacity-65"
          >
            {isGameRecordFileReading ? '対局記録を検証中' : '対局記録を読み込む'}
          </button>
          <button
            ref={newGameButtonRef}
            type="button"
            onClick={openNewGameDialog}
            disabled={!isNewGameAvailable || isViewingReplay || dialogsAreOpen}
            aria-haspopup="dialog"
            aria-expanded={isNewGameDialogOpen}
            className="rounded border border-emerald-800/70 bg-emerald-950/45 px-4 py-1.5 font-serif text-sm tracking-[0.1em] text-emerald-100 shadow-inner outline-none transition hover:border-emerald-600 hover:bg-emerald-900/55 focus-visible:ring-2 focus-visible:ring-amber-300 disabled:cursor-not-allowed disabled:border-stone-800 disabled:text-stone-600 disabled:opacity-65"
          >
            新しい対局
          </button>
        </div>
        {activeSessionBranch && (
          <p className="mt-1 text-xs text-sky-200" role="status">
            検討手順: {activeSessionBranch.displayName}
          </p>
        )}
        {workerSearchState.kind === 'thinking' && (
          <p className="mt-1 text-xs text-sky-200" role="status" aria-live="polite">
            AI思考中
          </p>
        )}
        {workerSearchState.kind === 'cancelled' && (
          <p className="mt-1 text-xs text-stone-300" role="status" aria-live="polite">
            時間制限AIの思考を中止しました。
          </p>
        )}
        {workerSearchState.kind === 'error' && (
          <p className="mt-1 text-xs text-rose-300" role="alert">
            時間制限AIの探索に失敗しました: {workerSearchState.message}
          </p>
        )}
        {(gameRecordSession?.branches.length ?? 0) > 0 && (
          <section
            className="mt-2 w-full max-w-2xl rounded border border-sky-900/70 bg-sky-950/20 px-3 py-2 text-left"
            aria-labelledby="session-records-title"
            aria-describedby="session-records-description"
          >
            <div className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
              <h2 id="session-records-title" className="font-serif text-sm tracking-[0.1em] text-sky-100">
                本譜と検討手順
              </h2>
              <p id="session-records-description" className="text-xs text-stone-400">
                このセッションの検討手順はJSONの対局記録としてまとめて保存・再読込できます。
              </p>
            </div>
            <div className="mt-2 flex flex-wrap gap-2" role="list">
              <div role="listitem">
                <button
                  type="button"
                  onClick={openReturnToMainlineDialog}
                  disabled={activeSessionBranch === null || dialogsAreOpen}
                  aria-current={activeSessionBranch === null ? 'page' : undefined}
                  className="rounded border border-amber-700/70 bg-amber-950/35 px-3 py-1 text-sm text-amber-100 outline-none transition hover:bg-amber-900/50 focus-visible:ring-2 focus-visible:ring-amber-300 disabled:cursor-not-allowed disabled:opacity-65"
                >
                  本譜
                </button>
              </div>
              {gameRecordSession?.branches.map((branch) => (
                <div key={branch.state.recordId} role="listitem">
                  <button
                    type="button"
                    onClick={() => branch.state.recordId && switchToSessionBranch(branch.state.recordId)}
                    disabled={
                      !branch.state.recordId ||
                      branch.state.recordId === activeSessionBranch?.state.recordId ||
                      dialogsAreOpen
                    }
                    aria-current={
                      branch.state.recordId === activeSessionBranch?.state.recordId ? 'page' : undefined
                    }
                    className="rounded border border-sky-700/70 bg-sky-950/45 px-3 py-1 text-sm text-sky-100 outline-none transition hover:bg-sky-900/60 focus-visible:ring-2 focus-visible:ring-amber-300 disabled:cursor-not-allowed disabled:opacity-65"
                  >
                    {branch.displayName}
                  </button>
                </div>
              ))}
            </div>
          </section>
        )}
        {exportNotice && (
          <p
            role={exportNotice.kind === 'error' ? 'alert' : 'status'}
            aria-live={exportNotice.kind === 'error' ? 'assertive' : 'polite'}
            className={`mt-1 max-w-full break-words text-xs ${
              exportNotice.kind === 'error' ? 'text-rose-300' : 'text-emerald-300'
            }`}
          >
            {exportNotice.message}
          </p>
        )}
      </header>

      {/* Main Table Section */}
      <main className="flex w-full max-w-[76rem] flex-1 min-w-0 flex-col items-center justify-center gap-4 md:gap-6 xl:flex-row xl:items-start">
        <div className="w-full min-w-0 max-w-4xl xl:flex-1">
          <ShogiTable
            squares={replaySnapshot?.squares ?? boardState.squares}
            senteHand={replaySnapshot?.senteHand ?? boardState.senteHand}
            goteHand={replaySnapshot?.goteHand ?? boardState.goteHand}
            status={replaySnapshot?.status ?? boardState.status}
            viewMode={boardState.viewMode}
            selectedSquare={selectedSquare}
            candidateSquares={candidateSquares}
            candidateKind={selection.kind === 'none' ? null : selection.kind === 'hand' ? 'drop' : 'move'}
            dropPieceType={selection.kind === 'hand' ? selection.pieceType : null}
            lastMove={replaySnapshot ? replaySnapshot.lastMove : boardState.lastMove}
            onSquareClick={isInteractionBlocked ? undefined : handleSquareClick}
            focusRequest={focusRequest}
            turn={displayedTurn}
            selectedHandPieceId={selectedHandPieceId}
            onHandPieceSelect={handleHandPieceSelect}
            pieceStandsDisabled={isInteractionBlocked}
          />
        </div>
        <div className="flex w-full max-w-md flex-col gap-4 xl:w-80 xl:max-w-sm">
          <MoveHistoryPanel
            history={boardState.history}
            result={!isViewingReplay && boardState.status === 'ended' ? boardState.result : null}
            resetKey={moveHistoryResetKey}
            availableHistoryIndexes={replayIndexSet}
            currentHistoryIndex={replayHistoryIndex}
            selectionDisabled={dialogsAreOpen}
            canGoToInitial={replayIndexSet.has(0) && replayHistoryIndex !== 0}
            canGoToPrevious={previousReplayIndex !== null}
            canGoToNext={nextReplayIndex !== null}
            isViewingReplay={isViewingReplay}
            canStartBranch={canStartBranch}
            onStartBranch={openBranchStartDialog}
            branchStartButtonRef={branchStartButtonRef}
            onSelectHistoryIndex={selectReplayPosition}
            onGoToInitial={() => selectReplayPosition(0)}
            onGoToPrevious={() => {
              if (previousReplayIndex !== null) selectReplayPosition(previousReplayIndex);
            }}
            onGoToNext={() => {
              if (nextReplayIndex !== null) selectReplayPosition(nextReplayIndex);
            }}
            onReturnToCurrent={returnToCurrentPosition}
          />
          <AiJudgmentPanel search={aiSearchDisplay} thinking={isWorkerSearchThinking} />
          {aiSearchDisplay && (
            <AiSearchResultPanel search={aiSearchDisplay} />
          )}
        </div>
      </main>
      <EvaluationPresetComparisonPanel display={comparisonDisplay} state={comparisonState} />
      <TimeLimitedQuiescenceComparisonPanel display={timeLimitedQuiescenceComparisonDisplay} state={timeLimitedQuiescenceComparisonState} />
      <QuiescenceComparisonPanel display={quiescenceComparisonDisplay} state={quiescenceComparisonState} />

      {pendingPromotion && !isEnded && (
        <PromotionDialog
          status={pendingPromotion.status}
          onPromote={() => completePromotionChoice('promote')}
          onDecline={() => completePromotionChoice('decline')}
          onCancel={cancelPromotion}
        />
      )}

      {isResignationDialogOpen && !isEnded && (
        <ResignationDialog
          resigningPlayer={boardState.turn}
          onConfirm={confirmResignation}
          onCancel={cancelResignation}
        />
      )}

      {isEnteringKingDialogOpen && !isEnded && (
        <EnteringKingDeclarationDialog
          evaluation={enteringKingEvaluation}
          onConfirm={confirmEnteringKing}
          onCancel={cancelEnteringKing}
        />
      )}

      {isAgreedJishogiDialogOpen && !isEnded && (
        <AgreedJishogiDialog
          evaluation={agreedJishogiEvaluation}
          proposal={agreedJishogiProposal}
          errorMessage={agreedJishogiError}
          onPropose={confirmAgreedJishogiProposal}
          onCancel={closeAgreedJishogiDialog}
          onAccept={acceptAgreedJishogiProposal}
          onReject={rejectAgreedJishogiProposal}
        />
      )}

      {isNewGameDialogOpen && (
        <NewGameDialog onConfirm={confirmNewGame} onCancel={cancelNewGame} />
      )}

      {pendingBranchHistoryIndex !== null && (
        <BranchReplayDialog
          kind="start"
          historyIndex={pendingBranchHistoryIndex}
          onConfirm={confirmBranchStart}
          onCancel={cancelBranchStart}
        />
      )}

      {isReturnToMainlineDialogOpen && activeSessionBranch && (
        <BranchReplayDialog
          kind="return"
          onConfirm={confirmReturnToMainline}
          onCancel={cancelReturnToMainline}
        />
      )}

      {pendingGameRecordImport && (
        <GameRecordImportDialog
          filename={pendingGameRecordImport.filename}
          exportedAt={pendingGameRecordImport.metadata.exportedAt}
          moveCount={pendingGameRecordImport.metadata.moveCount}
          isEnded={pendingGameRecordImport.metadata.isEnded}
          onConfirm={confirmGameRecordImport}
          onCancel={cancelGameRecordImport}
        />
      )}

      {pendingKifImport && (
        <KifImportDialog
          filename={pendingKifImport.filename}
          moveCount={pendingKifImport.metadata.moveCount}
          isEnded={pendingKifImport.metadata.isEnded}
          encoding={pendingKifImport.metadata.encoding}
          onConfirm={confirmKifImport}
          onCancel={cancelKifImport}
        />
      )}

      {/* Bottom Footer Notice */}
      <footer className="w-full max-w-4xl mt-8 pt-4 border-t border-stone-800/60 text-center">
        <p
          id="shogi-footer-notice"
          className="text-xs text-stone-400 font-sans tracking-wide select-none"
        >
          駒の移動・成り・駒打ち、王手表示・一般的な詰み判定・終局処理に対応しています。千日手・連続王手の千日手の終局処理に対応しています。500手規定による持将棋の終局処理に対応しています。合意による持将棋の終局処理に対応しています。投了による終局処理に対応しています。入玉宣言による終局処理に対応しています。確認後に平手初期局面から新しい対局を始められます。
        </p>
      </footer>
    </div>
  );
};

src/components/shogi/ShogiTable.tsx:
import React from 'react';
import { BoardSquare, BoardStatus, MoveRecord, Piece as PieceModel, PieceType, Player, TableViewMode } from '../../types/shogi';
import { ShogiBoard } from './ShogiBoard';
import { PieceStand } from './PieceStand';

interface ShogiTableProps {
  squares: BoardSquare[][];
  senteHand?: PieceModel[];
  goteHand?: PieceModel[];
  status?: BoardStatus;
  viewMode?: TableViewMode;
  className?: string;
  selectedSquare?: { row: number; col: number } | null;
  candidateSquares?: Array<{ row: number; col: number }>;
  candidateKind?: 'move' | 'drop' | null;
  dropPieceType?: PieceType | null;
  lastMove?: MoveRecord | null;
  onSquareClick?: (square: BoardSquare) => void;
  turn?: Player;
  selectedHandPieceId?: string | null;
  onHandPieceSelect?: (piece: PieceModel) => void;
  pieceStandsDisabled?: boolean;
  focusRequest?: { row: number; col: number; requestId: number } | null;
  topPlayerSlot?: React.ReactNode;
  bottomPlayerSlot?: React.ReactNode;
  leftPanelSlot?: React.ReactNode;
  rightPanelSlot?: React.ReactNode;
}

export const ShogiTable: React.FC<ShogiTableProps> = ({
  squares,
  senteHand = [],
  goteHand = [],
  status = 'preparation',
  viewMode = 'research',
  className = '',
  selectedSquare = null,
  candidateSquares = [],
  candidateKind = null,
  dropPieceType = null,
  lastMove = null,
  onSquareClick,
  turn = 'sente',
  selectedHandPieceId = null,
  onHandPieceSelect,
  pieceStandsDisabled = false,
  focusRequest = null,
  topPlayerSlot,
  bottomPlayerSlot,
  leftPanelSlot,
  rightPanelSlot,
}) => {
  return (
    <div
      id="shogi-match-table"
      data-view={viewMode}
      data-board-status={status}
      className={`relative w-full max-w-4xl mx-auto rounded-2xl p-4 sm:p-8 md:p-10 transition-all duration-300 ${className}`}
      style={{
        // Deep dark matte studio table texture matching the reference image
        background:
          'radial-gradient(ellipse at 50% 50%, #1e1b18 0%, #141210 50%, #0d0c0a 100%)',
        boxShadow: `
          0 25px 50px -12px rgba(0, 0, 0, 0.9),
          inset 0 1px 1px rgba(255, 255, 255, 0.05),
          inset 0 0 80px rgba(0, 0, 0, 0.7)
        `,
        border: '1px solid rgba(70, 55, 45, 0.25)',
      }}
    >
      {/* Studio Lighting Vignette Overlay */}
      <div
        aria-hidden="true"
        className="absolute inset-0 pointer-events-none rounded-2xl opacity-40"
        style={{
          backgroundImage:
            'radial-gradient(circle at 50% 48%, rgba(245, 180, 100, 0.08) 0%, transparent 65%)',
        }}
      />

      {/* Future Top Player Slot */}
      {topPlayerSlot && <div className="mb-3 w-full flex justify-center">{topPlayerSlot}</div>}

      {/* Main Board & Komadai Layout (Centered vertically, matching reference image) */}
      <div className="relative z-10 flex flex-col items-center gap-5 sm:gap-7">
        {/* Top: Gote's Piece Stand (Centered above the board as in the image) */}
        <div className="w-full flex justify-center">
          <PieceStand
            player="gote"
            pieces={goteHand}
            isActive={!pieceStandsDisabled && turn === 'gote' && Boolean(onHandPieceSelect)}
            selectedPieceId={selectedHandPieceId}
            onPieceSelect={onHandPieceSelect}
          />
        </div>

        {/* Center: The Shogi Board (Slight top-down perspective, high clarity) */}
        <div
          id="shogi-board-perspective-container"
          className="flex justify-center items-center w-full transition-transform duration-300"
          style={{
            perspective: '1400px',
          }}
        >
          <div
            className="transform-gpu transition-all duration-300"
            style={{
              transform:
                viewMode === 'research'
                  ? 'rotateX(2.5deg)'
                  : viewMode === 'spectator'
                  ? 'rotateX(8deg) rotateY(-4deg)'
                  : 'none',
              transformOrigin: 'center bottom',
            }}
          >
            <ShogiBoard
              squares={squares}
              status={status}
              selectedSquare={selectedSquare}
              candidateSquares={candidateSquares}
              candidateKind={candidateKind}
              dropPieceType={dropPieceType}
              lastMove={lastMove}
              onSquareClick={onSquareClick}
              focusRequest={focusRequest}
            />
          </div>
        </div>

        {/* Bottom: Sente's Piece Stand (Centered below the board as in the image) */}
        <div className="w-full flex justify-center">
          <PieceStand
            player="sente"
            pieces={senteHand}
            isActive={!pieceStandsDisabled && turn === 'sente' && Boolean(onHandPieceSelect)}
            selectedPieceId={selectedHandPieceId}
            onPieceSelect={onHandPieceSelect}
          />
        </div>
      </div>

      {/* Future Bottom Player Slot */}
      {bottomPlayerSlot && <div className="mt-3 w-full flex justify-center">{bottomPlayerSlot}</div>}

      {/* Future Side Panel Slots */}
      {leftPanelSlot && (
        <div className="hidden lg:block absolute left-4 top-1/2 -translate-y-1/2">
          {leftPanelSlot}
        </div>
      )}
      {rightPanelSlot && (
        <div className="hidden lg:block absolute right-4 top-1/2 -translate-y-1/2">
          {rightPanelSlot}
        </div>
      )}
    </div>
  );
};

src/components/shogi/TimeLimitedQuiescen:
import { Fragment } from 'react';
import type { Player } from '../../types/shogi';
import type { TimeLimitedQuiescenceComparisonResult } from '../../domain/shogi/timeLimitedQuiescenceComparison';
import { quiescenceComparisonName } from './QuiescenceComparisonPanel';
import { formatSenteEvaluation } from './searchEvaluationDisplay';

export interface TimeLimitedQuiescenceComparisonDisplay {
  perspective: Player;
  entries: readonly {
    result: TimeLimitedQuiescenceComparisonResult;
    principalVariationNotations: readonly string[];
  }[];
}

const normalStatistics = [
  ['訪問局面数', 'visitedPositionCount', 'totalVisitedPositionCount'],
  ['カットオフ回数', 'cutoffCount', 'totalCutoffCount'],
  ['スキップ手数', 'skippedActionCount', 'totalSkippedActionCount'],
] as const;
const tacticalStatistics = [
  ['開始した葉の数', 'quiescenceLeafCount', 'totalQuiescenceLeafCount'],
  ['訪問局面数', 'quiescenceVisitedPositionCount', 'totalQuiescenceVisitedPositionCount'],
  ['カットオフ回数', 'quiescenceCutoffCount', 'totalQuiescenceCutoffCount'],
  ['スキップ手数', 'quiescenceSkippedActionCount', 'totalQuiescenceSkippedActionCount'],
] as const;

export function TimeLimitedQuiescenceComparisonPanel({ display, state }: {
  display: TimeLimitedQuiescenceComparisonDisplay | null;
  state: { kind: 'idle' | 'thinking' | 'cancelled' } | { kind: 'error'; message: string };
}) {
  return <section aria-labelledby="time-limited-quiescence-title" className="mx-auto mt-4 w-full min-w-0 max-w-6xl rounded border border-sky-800/70 bg-sky-950/30 p-3 text-xs text-sky-100 [overflow-wrap:anywhere]">
    <h2 id="time-limited-quiescence-title" className="font-serif text-sm">同一時間の静止探索比較</h2>
    <p className="mt-2 text-stone-300">同一局面・標準評価・最大深さ4で、各条件に独立した1秒を与えて順番に解析します。盤面には着手しません。</p>
    <p className="mt-1 text-stone-400">全体では約3秒以上かかる場合があります。各条件は深さ1から協調的に期限を確認しますが、単一の同期処理やOS負荷により1秒を超える場合があります。</p>
    <p className="mt-1 text-stone-400">時間だけで棋力や設定の優劣を判断せず、最適設定を自動選択しません。主変化は完了深さに静止探索の追加手数を加えた長さまで伸びる場合があります。</p>
    <p className="mt-1 text-stone-400">参考処理時間は探索API全体（未完了反復を含む）です。Worker起動・通信・描画は含みません。統計は完了反復のみです。</p>
    {state.kind === 'thinking' && <p role="status" className="mt-2">静止探索の3条件を順番に解析中（各1秒）</p>}
    {state.kind === 'cancelled' && <p role="status" className="mt-2">同一時間の静止探索比較を中止しました。</p>}
    {state.kind === 'error' && <p role="alert" className="mt-2">同一時間の静止探索比較に失敗しました: {state.message}</p>}
    {display && state.kind === 'idle' && <>
      <p className="mt-2">先手基準：＋は先手有利、−は後手有利、0は互角です。</p>
      <div className="mt-3 grid min-w-0 grid-cols-1 gap-3 lg:grid-cols-3">
        {display.entries.map(({ result, principalVariationNotations }) => {
          const name = quiescenceComparisonName(result.quiescenceMaxTacticalDepth);
          return <article key={name} aria-label={name} className="min-w-0 space-y-3 rounded border border-sky-900 p-3">
            <h3 className="text-sm font-semibold">{name}</h3>
            {result.resultSource === 'partial-root' && <p>部分探索・深さ1未完了：選択候補の評価・PV（全合法手の比較は未完了）</p>}
            <dl className="grid grid-cols-2 gap-2">
              <dt>推奨手</dt><dd>{principalVariationNotations[0] ?? '指せる手はありません'}</dd>
              <dt>評価値</dt><dd>{result.resultSource === 'fallback' ? '未評価' : `先手 ${formatSenteEvaluation(result.selectedEvaluation ?? result.evaluationBreakdown?.total ?? null, display.perspective)}`}</dd>
              <dt>完了深さ／指定最大深さ</dt><dd>{result.completedDepth} / {result.requestedMaxDepth} ply</dd>
              <dt>時間切れ</dt><dd>{result.timedOut ? 'あり' : 'なし（最大深さ完了）'}</dd>
              <dt>API全体の参考処理時間</dt><dd>{result.elapsedMilliseconds.toFixed(1)} ms</dd>
            </dl>
            <div><h4>主変化</h4>{result.resultSource === 'fallback'
              ? <p>未探索</p> : principalVariationNotations.length > 0
              ? <ol className="mt-1 list-decimal space-y-1 pl-5">{principalVariationNotations.map((notation, index) => <li key={index}>{notation}</li>)}</ol>
              : <p>手順なし</p>}</div>
            {([false, true] as const).map((total) => <Fragment key={String(total)}>
              {([['通常探索', normalStatistics], ['静止探索', tacticalStatistics]] as const).map(([label, keys]) =>
                <div key={label} className="border-t border-sky-900 pt-2">
                  <h4>{total ? '全完了反復合計' : '最深完了反復'}の{label}</h4>
                  <dl className="mt-1 grid grid-cols-2 gap-2">{keys.map(([title, current, sum]) =>
                    <Fragment key={current}><dt>{title}</dt><dd>{result[total ? sum : current]}</dd></Fragment>)}</dl>
                </div>)}
            </Fragment>)}
          </article>;
        })}
      </div>
    </>}
  </section>;
}

