/**
 * One-ply material AI built from the public legal-action and evaluation APIs.
 *
 * This module chooses an action only. Applying the selected action to the
 * actual game remains the responsibility of executeLegalAction's caller.
 */
import type { BoardState, Player } from '../../types/shogi';
import { executeLegalAction, getLegalActions, type LegalAction } from './legalActions';
import {
  DEFAULT_MATERIAL_VALUE_TABLE,
} from './materialEvaluation';
import { evaluateSearchPosition, type SearchEvaluationConfig } from './twoPlyMinimaxAi';
import { cloneBoardState } from './replay';

/**
 * Selects the legal action whose resulting non-terminal position has the
 * highest material-plus-piece-square evaluation from the supplied perspective.
 *
 * Every candidate is applied to an independent cloned state. The perspective
 * intentionally remains fixed even though applying a move changes turn. Ties
 * retain the first action returned by getLegalActions, preserving its stable
 * ordering. Returns null when there are no legal actions.
 */
export function selectBestMaterialAction(
  state: BoardState,
  perspective: Player,
  evaluation: SearchEvaluationConfig = DEFAULT_MATERIAL_VALUE_TABLE
): LegalAction | null {
  const actions = getLegalActions(state);
  let bestAction: LegalAction | null = null;
  let bestEvaluation = Number.NEGATIVE_INFINITY;

  for (const action of actions) {
    const execution = executeLegalAction(cloneBoardState(state), action);
    if (execution.type !== 'applied') continue;

    const candidateEvaluation = evaluateSearchPosition(execution.state, perspective, evaluation);
    if (candidateEvaluation > bestEvaluation) {
      bestAction = action;
      bestEvaluation = candidateEvaluation;
    }
  }

  return bestAction;
}

src/domain/shogi/materialEvaluation.ts:
/**
 * Material-only position evaluation for future search consumers.
 *
 * This is deliberately separate from the official jishogi point calculation:
 * it compares owned material with AI-oriented values and does not decide a
 * game result.
 */
import type { BoardState, Piece, PieceType, Player } from '../../types/shogi';

type PromotablePieceType = Exclude<PieceType, 'gold' | 'king'>;

/** Values for unpromoted pieces and each legally promotable piece type. */
export interface MaterialValueTable {
  readonly unpromoted: Readonly<Record<PieceType, number>>;
  readonly promoted: Readonly<Record<PromotablePieceType, number>>;
}

/** Default AI material values. Kings have no material value. */
export const DEFAULT_MATERIAL_VALUE_TABLE = {
  unpromoted: {
    pawn: 100,
    lance: 300,
    knight: 300,
    silver: 400,
    gold: 500,
    bishop: 800,
    rook: 1000,
    king: 0,
  },
  promoted: {
    pawn: 500,
    lance: 500,
    knight: 500,
    silver: 500,
    bishop: 1000,
    rook: 1200,
  },
} as const satisfies MaterialValueTable;

function isPromotablePieceType(type: PieceType): type is PromotablePieceType {
  return type !== 'gold' && type !== 'king';
}

/**
 * Returns the material value of a piece while it remains on the board.
 * Other board-only heuristics reuse this so promoted pieces share this module's
 * single material-value definition.
 */
export function getBoardPieceMaterialValue(piece: Piece, valueTable: MaterialValueTable): number {
  if (piece.isPromoted && isPromotablePieceType(piece.type)) {
    return valueTable.promoted[piece.type];
  }
  return valueTable.unpromoted[piece.type];
}

function getHandPieceValue(piece: Piece, valueTable: MaterialValueTable): number {
  // Captured pieces are unpromoted in hand, regardless of the optional flag.
  return valueTable.unpromoted[piece.type];
}

function getOwnedMaterialTotal(
  state: BoardState,
  player: Player,
  valueTable: MaterialValueTable
): number {
  let total = 0;

  for (const row of state.squares) {
    for (const square of row) {
      if (square.piece?.player === player) {
        total += getBoardPieceMaterialValue(square.piece, valueTable);
      }
    }
  }

  for (const handPiece of state.senteHand) {
    if (handPiece.player === player) total += getHandPieceValue(handPiece, valueTable);
  }
  for (const handPiece of state.goteHand) {
    if (handPiece.player === player) total += getHandPieceValue(handPiece, valueTable);
  }

  return total;
}

/**
 * Returns owned material from the explicit perspective: that side's total
 * minus the opponent's. Turn, terminal result, and legal-move state are not
 * part of this material-only evaluation.
 */
export function evaluateMaterial(
  state: BoardState,
  perspective: Player,
  valueTable: MaterialValueTable = DEFAULT_MATERIAL_VALUE_TABLE
): number {
  const opponent = perspective === 'sente' ? 'gote' : 'sente';
  return getOwnedMaterialTotal(state, perspective, valueTable) -
    getOwnedMaterialTotal(state, opponent, valueTable);
}

src/domain/shogi/moveLimitJishogi.ts:
import type {
  BoardState,
  MoveLimitJishogiState,
  Player,
} from '../../types/shogi';

export const JISHOGI_MOVE_LIMIT = 500;

export type MoveLimitJishogiAdjudication =
  | { kind: 'not_reached' }
  | { kind: 'waiting'; state: MoveLimitJishogiState }
  | { kind: 'draw' };

function isPendingState(
  state: MoveLimitJishogiState | null | undefined
): state is MoveLimitJishogiState {
  return (
    state?.kind === 'awaiting_continuous_check_end' &&
    (state.checkingPlayer === 'sente' || state.checkingPlayer === 'gote')
  );
}

/**
 * Classifies the 500-move jishogi rule after an already-legal move.
 * `moveNumber` is the next move number, so completed moves are `moveNumber - 1`.
 */
export function classifyMoveLimitJishogi(
  state: BoardState,
  movingPlayer: Player,
  gaveCheck: boolean
): MoveLimitJishogiAdjudication {
  const pending = isPendingState(state.moveLimitJishogi)
    ? state.moveLimitJishogi
    : null;

  if (pending) {
    if (movingPlayer !== pending.checkingPlayer || gaveCheck) {
      return { kind: 'waiting', state: pending };
    }
    return { kind: 'draw' };
  }

  const completedMoves = state.moveNumber - 1;
  if (completedMoves < JISHOGI_MOVE_LIMIT) {
    return { kind: 'not_reached' };
  }

  if (gaveCheck) {
    return {
      kind: 'waiting',
      state: {
        kind: 'awaiting_continuous_check_end',
        checkingPlayer: movingPlayer,
      },
    };
  }

  return { kind: 'draw' };
}

src/domain/shogi/moves.ts:
/**
 * Shogi Move Generation & Legality Engine
 * Pure functions to compute pseudo-legal moves, filter out illegal moves (王手放置・自殺手・行き所のない駒),
 * and produce strictly legal moves according to standard Shogi rules.
 */

import { BoardSquare, Piece, Player } from '../../types/shogi';
import { Coordinate, isWithinBoard } from './coordinates';
import {
  getPieceAttackPattern,
  isKingInCheck,
  isKingInCheckProfiled,
} from './attacks';
import { isPromotionRequired } from './promotion';
import type { ActionValidationProbe } from './actionValidationDiagnostics';
import type { SearchDiagnostics } from './searchDiagnostics';

/**
 * Checks if a move results in a piece having no legal forward moves ("行き所のない駒").
 * Applies only to unpromoted Pawns, Lances (cannot reach rank 1 for Sente / rank 9 for Gote)
 * and Knights (cannot reach ranks 1-2 for Sente / ranks 8-9 for Gote).
 */
export function isDeadPieceMove(piece: Piece, to: Coordinate): boolean {
  return isPromotionRequired(piece, to);
}

/**
 * Generates pseudo-legal moves for a piece based on geometric movement,
 * board boundaries, piece collision (stopping at obstacles), and own-piece blocking.
 * Excludes capturing opponent King directly.
 */
export function getPseudoLegalMoves(
  squares: BoardSquare[][],
  from: Coordinate,
  piece: Piece
): Coordinate[] {
  const candidates: Coordinate[] = [];
  const pattern = getPieceAttackPattern(piece);

  // Check single step moves
  for (const [dr, dc] of pattern.stepOffsets) {
    const targetRow = from.row + dr;
    const targetCol = from.col + dc;

    if (!isWithinBoard(targetRow, targetCol)) continue;

    const targetSquare = squares[targetRow][targetCol];
    if (!targetSquare.piece) {
      candidates.push({ row: targetRow, col: targetCol });
    } else if (targetSquare.piece.player !== piece.player) {
      // Opponent piece - can capture unless King
      if (targetSquare.piece.type !== 'king') {
        candidates.push({ row: targetRow, col: targetCol });
      }
    }
  }

  // Check sliding ray moves
  for (const [dr, dc] of pattern.rayDirections) {
    let currRow = from.row + dr;
    let currCol = from.col + dc;

    while (isWithinBoard(currRow, currCol)) {
      const targetSquare = squares[currRow][currCol];

      if (!targetSquare.piece) {
        candidates.push({ row: currRow, col: currCol });
      } else {
        if (targetSquare.piece.player !== piece.player) {
          // Can capture opponent piece unless King, then stop ray
          if (targetSquare.piece.type !== 'king') {
            candidates.push({ row: currRow, col: currCol });
          }
        }
        break; // Blocked by any piece
      }

      currRow += dr;
      currCol += dc;
    }
  }

  return candidates;
}

/**
 * Creates a lightweight simulated 9x9 board with the move applied, for checking king safety.
 */
export function simulateMoveSquares(
  squares: BoardSquare[][],
  from: Coordinate,
  to: Coordinate
): BoardSquare[][] {
  const nextSquares = squares.map((row) =>
    row.map((sq) => ({
      ...sq,
      piece: sq.piece ? { ...sq.piece } : null,
    }))
  );

  if (!isWithinBoard(from.row, from.col) || !isWithinBoard(to.row, to.col)) {
    return nextSquares;
  }

  const movingPiece = nextSquares[from.row][from.col].piece;
  if (!movingPiece) return nextSquares;

  nextSquares[from.row][from.col].piece = null;
  nextSquares[to.row][to.col].piece = { ...movingPiece };

  return nextSquares;
}

/** King-safety readers only need the two changed squares. Never expose this shared copy. */
function simulateMoveSquaresForKingSafety(
  squares: BoardSquare[][],
  from: Coordinate,
  to: Coordinate
): BoardSquare[][] {
  const nextSquares = squares.slice();
  nextSquares[from.row] = squares[from.row].slice();
  if (to.row !== from.row) nextSquares[to.row] = squares[to.row].slice();
  nextSquares[from.row][from.col] = { ...squares[from.row][from.col], piece: null };
  nextSquares[to.row][to.col] = {
    ...squares[to.row][to.col], piece: squares[from.row][from.col].piece,
  };
  return nextSquares;
}

/**
 * Computes strictly legal moves for a piece at `from`.
 * Validates:
 * 1. Piece exists and belongs to current turn (if specified).
 * 2. Basic geometric movements.
 * 3. Does NOT leave own King in check (resolves checks, prevents self-check & pinned piece violations).
 * Mandatory-promotion destinations remain legal candidates; executeMove validates the choice.
 */
export function getLegalMoves(
  squares: BoardSquare[][],
  from: Coordinate | null | undefined,
  currentTurn?: Player,
  qDiagnostics?: SearchDiagnostics,
  probe?: ActionValidationProbe
): Coordinate[] {
  if (!from || !isWithinBoard(from.row, from.col)) {
    return [];
  }

  const square = squares[from.row][from.col];
  if (!square || !square.piece) {
    return [];
  }

  const piece = square.piece;
  if (currentTurn && piece.player !== currentTurn) {
    return [];
  }

  if (qDiagnostics || probe) {
    const generate = () => getPseudoLegalMoves(squares, from, piece);
    const generateMeasured = () => qDiagnostics
      ? qDiagnostics.measure('q-board-pseudo', generate) : generate();
    const pseudoMoves = probe ? probe.measure('pseudo', generateMeasured) : generateMeasured();
    if (qDiagnostics) qDiagnostics.qLegalCounts.boardPseudo += pseudoMoves.length;
    const legalMoves: Coordinate[] = [];
    for (const dest of pseudoMoves) {
      const validate = () => {
        const simulate = () => simulateMoveSquaresForKingSafety(squares, from, dest);
        const simulateMeasured = () => qDiagnostics
          ? qDiagnostics.measure('q-board-simulate', simulate) : simulate();
        const simulatedSquares = probe ? probe.measure('board-setup', simulateMeasured) : simulateMeasured();
        const check = () => qDiagnostics?.checkInternals
          ? isKingInCheckProfiled(simulatedSquares, piece.player, qDiagnostics.checkInternals.board)
          : isKingInCheck(simulatedSquares, piece.player);
        const checkMeasured = () => qDiagnostics ? qDiagnostics.measure('q-board-own-check', check) : check();
        return !(probe ? probe.measure('own-check', checkMeasured) : checkMeasured());
      };
      if (probe ? probe.measure('validation', validate) : validate()) legalMoves.push(dest);
    }
    if (qDiagnostics) qDiagnostics.qLegalCounts.boardLegal += legalMoves.length;
    return legalMoves;
  }

  const pseudoMoves = getPseudoLegalMoves(squares, from, piece);
  const legalMoves: Coordinate[] = [];

  for (const dest of pseudoMoves) {
    // Simulate move and check if own king is left in check
    const simulatedSquares = simulateMoveSquaresForKingSafety(squares, from, dest);
    if (isKingInCheck(simulatedSquares, piece.player)) {
      continue;
    }

    legalMoves.push(dest);
  }

  return legalMoves;
}

/** Exact existence query using the same candidates and king-safety simulation.
 * No legal destination list is materialized and validation stops at the first.
 */
export function hasLegalMove(
  squares: BoardSquare[][],
  from: Coordinate,
  currentTurn?: Player
): boolean {
  if (!isWithinBoard(from.row, from.col)) return false;
  const piece = squares[from.row]?.[from.col]?.piece;
  if (!piece || (currentTurn && piece.player !== currentTurn)) return false;
  return getPseudoLegalMoves(squares, from, piece).some(to =>
    !isKingInCheck(simulateMoveSquaresForKingSafety(squares, from, to), piece.player));
}

/** Alias for backward-compatibility with UI components. */
export function getMoveCandidates(
  squares: BoardSquare[][],
  from: Coordinate | null | undefined,
  currentTurn?: Player
): Coordinate[] {
  return getLegalMoves(squares, from, currentTurn);
}

src/domain/shogi/pairedSelfPlayMatch.ts:
import type { BoardState } from '../../types/shogi';
import { runSelfPlayGame, type SelfPlayGameResult, type SelfPlayParticipant } from './selfPlayGame';

export type PairedSelfPlayParticipantId = 'A' | 'B';

/** Game number determines the seats, including when narrowing a game union. */
export type PairedSelfPlaySeats =
  | { gameNumber: 1; sente: 'A'; gote: 'B' }
  | { gameNumber: 2; sente: 'B'; gote: 'A' };

export type PairedSelfPlayOutcome = 'a_win' | 'b_win' | 'draw' | 'max_plies' | 'failed';

export type PairedSelfPlayGame = PairedSelfPlaySeats & {
  result: SelfPlayGameResult;
  outcome: PairedSelfPlayOutcome;
};

export interface PairedSelfPlaySummary {
  aWins: number;
  bWins: number;
  draws: number;
  maxPlies: number;
  failures: number;
}

export interface PairedSelfPlayMatchResult {
  games: [
    PairedSelfPlayGame & { gameNumber: 1 },
    PairedSelfPlayGame & { gameNumber: 2 },
  ];
  summary: PairedSelfPlaySummary;
}

function outcomeFor(result: SelfPlayGameResult, seats: PairedSelfPlaySeats): PairedSelfPlayOutcome {
  if (result.status !== 'ended') return result.status;
  const winner = result.gameResult.winner;
  if (winner === null) return 'draw';
  return seats[winner] === 'A' ? 'a_win' : 'b_win';
}

/** Runs exactly two independent synchronous games from the supplied position.
 * BoardState cloning, search protection and adjudication belong to runSelfPlayGame.
 * Injected searches/settings own their side effects, clocks and termination.
 */
export function runPairedSelfPlayMatch<ASettings, BSettings>(options: {
  initialState: BoardState;
  a: SelfPlayParticipant<ASettings>;
  b: SelfPlayParticipant<BSettings>;
  maxPlies: number;
}): PairedSelfPlayMatchResult {
  const { initialState, a, b, maxPlies } = options;
  const firstSeats = { gameNumber: 1, sente: 'A', gote: 'B' } as const;
  const secondSeats = { gameNumber: 2, sente: 'B', gote: 'A' } as const;
  const first = runSelfPlayGame({ initialState, sente: a, gote: b, maxPlies });
  // A failed or truncated first game is still an observation; always run game 2.
  const second = runSelfPlayGame({ initialState, sente: b, gote: a, maxPlies });
  const games: PairedSelfPlayMatchResult['games'] = [
    { ...firstSeats, result: first, outcome: outcomeFor(first, firstSeats) },
    { ...secondSeats, result: second, outcome: outcomeFor(second, secondSeats) },
  ];
  const summary: PairedSelfPlaySummary = { aWins: 0, bWins: 0, draws: 0, maxPlies: 0, failures: 0 };
  const countKey = {
    a_win: 'aWins', b_win: 'bWins', draw: 'draws', max_plies: 'maxPlies', failed: 'failures',
  } as const satisfies Record<PairedSelfPlayOutcome, keyof PairedSelfPlaySummary>;
  for (const game of games) summary[countKey[game.outcome]]++;
  return { games, summary };
}

src/domain/shogi/pieceSquareEvaluation.t:
/**
 * Piece-square position evaluation, deliberately independent from material.
 *
 * Scores use the same small unit as the material table. The largest default
 * positional difference for one piece is 5 points, far below a pawn (100).
 * Every grid is written from Sente's view: row 8 is Sente's home rank and
 * row 0 is the far rank. Gote uses the 180-degree counterpart (8 - row,
 * 8 - col), so both players share precisely the same tables.
 */
import type { BoardState, Piece, PieceType, Player } from '../../types/shogi';

type PromotablePieceType = Exclude<PieceType, 'gold' | 'king'>;
export type PieceSquareGrid = readonly (readonly number[])[];

export interface PieceSquareValueTable {
  readonly unpromoted: Readonly<Record<PieceType, PieceSquareGrid>>;
  readonly promoted: Readonly<Record<PromotablePieceType, PieceSquareGrid>>;
}

function gridByRank(rankValues: readonly number[], centerFileBonus = 0): PieceSquareGrid {
  if (rankValues.length !== 9) throw new Error('A piece-square rank definition must contain nine rows.');
  return rankValues.map((rankValue) => [
    rankValue,
    rankValue,
    rankValue + centerFileBonus,
    rankValue + centerFileBonus,
    rankValue + centerFileBonus,
    rankValue + centerFileBonus,
    rankValue + centerFileBonus,
    rankValue,
    rankValue,
  ] as const);
}

/**
 * Conservative default piece-square tables. Pawns, lances, knights, and
 * silvers receive a modest advance/activity preference. Golds stay nearly
 * flat, and bishops/rooks get only a small central-work preference rather
 * than a bonus for entering the far ranks. Kings are intentionally neutral:
 * king safety is outside this evaluation.
 */
export const DEFAULT_PIECE_SQUARE_VALUE_TABLE = {
  unpromoted: {
    pawn: gridByRank([1, 2, 3, 3, 2, 1, 0, 0, -1], 1),
    lance: gridByRank([0, 1, 2, 2, 1, 0, 0, 0, -1]),
    knight: gridByRank([-2, -1, 1, 2, 2, 1, 0, 0, -1], 1),
    silver: gridByRank([0, 1, 2, 3, 3, 2, 1, 0, -1], 1),
    gold: gridByRank([0, 0, 0, 1, 1, 1, 1, 0, 0]),
    bishop: gridByRank([0, 0, 1, 1, 2, 1, 1, 0, 0], 1),
    rook: gridByRank([0, 0, 1, 1, 2, 1, 1, 0, 0], 1),
    king: gridByRank([0, 0, 0, 0, 0, 0, 0, 0, 0]),
  },
  promoted: {
    pawn: gridByRank([0, 1, 2, 2, 2, 1, 1, 0, 0], 1),
    lance: gridByRank([0, 1, 2, 2, 2, 1, 1, 0, 0], 1),
    knight: gridByRank([0, 1, 2, 2, 2, 1, 1, 0, 0], 1),
    silver: gridByRank([0, 1, 2, 2, 2, 1, 1, 0, 0], 1),
    bishop: gridByRank([0, 1, 1, 2, 2, 2, 1, 1, 0], 1),
    rook: gridByRank([0, 1, 1, 2, 2, 2, 1, 1, 0], 1),
  },
} as const satisfies PieceSquareValueTable;

function isPromotablePieceType(type: PieceType): type is PromotablePieceType {
  return type !== 'gold' && type !== 'king';
}

/** Returns the shared Sente-oriented table coordinate for a board square. */
export function toSentePieceSquareCoordinate(player: Player, row: number, col: number): { row: number; col: number } {
  return player === 'sente' ? { row, col } : { row: 8 - row, col: 8 - col };
}

function pieceSquareGrid(piece: Piece, table: PieceSquareValueTable): PieceSquareGrid {
  if (piece.isPromoted && isPromotablePieceType(piece.type)) return table.promoted[piece.type];
  return table.unpromoted[piece.type];
}

function ownedPieceSquareTotal(state: BoardState, player: Player, table: PieceSquareValueTable): number {
  let total = 0;
  for (let row = 0; row < state.squares.length; row += 1) {
    for (let col = 0; col < state.squares[row].length; col += 1) {
      const piece = state.squares[row][col].piece;
      if (!piece || piece.player !== player) continue;
      const coordinate = toSentePieceSquareCoordinate(piece.player, row, col);
      total += pieceSquareGrid(piece, table)[coordinate.row][coordinate.col];
    }
  }
  // Hand pieces have no board coordinate and deliberately receive no score.
  return total;
}

/**
 * Returns board-position points from the explicit perspective. This has no
 * dependency on turn, terminal state, history, or hand pieces.
 */
export function evaluatePieceSquarePosition(
  state: BoardState,
  perspective: Player,
  valueTable: PieceSquareValueTable = DEFAULT_PIECE_SQUARE_VALUE_TABLE
): number {
  const opponent = perspective === 'sente' ? 'gote' : 'sente';
  return ownedPieceSquareTotal(state, perspective, valueTable) -
    ownedPieceSquareTotal(state, opponent, valueTable);
}

