import { handleTimeLimitedQuiescenceComparisonWorkerRequest } from './timeLimitedQuiescenceComparisonWorkerHandler';
import type { TimeLimitedQuiescenceComparisonWorkerRequest } from './timeLimitedQuiescenceComparisonWorkerProtocol';
import { handleQuiescenceComparisonWorkerRequest } from './quiescenceComparisonWorkerHandler';
import type { QuiescenceComparisonWorkerRequest } from './quiescenceComparisonWorkerProtocol';
import { handleTimeLimitedIterativeDeepeningAlphaBetaSearchWorkerRequest } from './timeLimitedIterativeDeepeningAlphaBetaWorkerHandler';
import { handleEvaluationPresetComparisonWorkerRequest } from './evaluationPresetComparisonWorkerHandler';
import type { EvaluationPresetComparisonWorkerRequest } from './evaluationPresetComparisonWorkerProtocol';
import type {
  TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerRequest,
} from './timeLimitedIterativeDeepeningAlphaBetaWorkerProtocol';

self.addEventListener(
  'message',
  (event: MessageEvent<TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerRequest | EvaluationPresetComparisonWorkerRequest | QuiescenceComparisonWorkerRequest | TimeLimitedQuiescenceComparisonWorkerRequest>) => {
    switch (event.data.type) {
      case 'compare-time-limited-quiescence-settings':
        self.postMessage(handleTimeLimitedQuiescenceComparisonWorkerRequest(event.data));
        break;
      case 'compare-evaluation-presets':
        self.postMessage(handleEvaluationPresetComparisonWorkerRequest(event.data));
        break;
      case 'compare-quiescence-settings':
        self.postMessage(handleQuiescenceComparisonWorkerRequest(event.data));
        break;
      case 'run-time-limited-iterative-deepening-alpha-beta-search':
        self.postMessage(handleTimeLimitedIterativeDeepeningAlphaBetaSearchWorkerRequest(event.data));
        break;
    }
  }
);

import {
  analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch,
  type AlphaBetaSearchOptions,
  type TimeLimitedIterativeDeepeningAlphaBetaSearchResult,
} from '../domain/shogi/twoPlyAlphaBetaAi';
import type { SearchEvaluationConfig } from '../domain/shogi/twoPlyMinimaxAi';
import { DEFAULT_SEARCH_EVALUATION_PRESET_ID, resolveSearchEvaluationPreset } from '../domain/shogi/searchEvaluationPresets';
import type {
  TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerFailureResponse,
  TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerRequest,
  TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerResponse,
} from './timeLimitedIterativeDeepeningAlphaBetaWorkerProtocol';

export type TimeLimitedIterativeDeepeningAlphaBetaSearch = (
  state: TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerRequest['state'],
  maxDepth: number,
  timeLimitMilliseconds: number,
  evaluation?: SearchEvaluationConfig,
  clock?: () => number,
  options?: AlphaBetaSearchOptions
) => TimeLimitedIterativeDeepeningAlphaBetaSearchResult;

function resolveWorkerQuiescenceOptions(value: unknown): {
  readonly maxTacticalDepth: 1 | 2;
} | undefined {
  if (value === undefined) return undefined;
  if (value === 1 || value === 2) return { maxTacticalDepth: value };
  throw new RangeError('Worker quiescence maximum tactical depth must be either 1 or 2 when supplied.');
}

function toWorkerFailureResponse(
  requestId: string | null,
  error: unknown
): TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerFailureResponse {
  if (error instanceof Error) {
    return {
      type: 'time-limited-iterative-deepening-alpha-beta-search-failed',
      requestId,
      errorName: error.name || 'Error',
      errorMessage: error.message || 'Worker search failed.',
    };
  }

  return {
    type: 'time-limited-iterative-deepening-alpha-beta-search-failed',
    requestId,
    errorName: 'UnknownWorkerSearchError',
    errorMessage: typeof error === 'string' && error.length > 0
      ? error
      : 'Worker search failed with a non-Error value.',
  };
}

/**
 * Pure worker-side request handling. Keeping this independent of `self` makes
 * search behavior testable without a browser Worker implementation.
 */
export function handleTimeLimitedIterativeDeepeningAlphaBetaSearchWorkerRequest(
  request: TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerRequest,
  search: TimeLimitedIterativeDeepeningAlphaBetaSearch =
    analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch
): TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerResponse {
  try {
    const evaluationPresetId = request.evaluationPresetId === undefined
      ? DEFAULT_SEARCH_EVALUATION_PRESET_ID : request.evaluationPresetId;
    const evaluation = resolveSearchEvaluationPreset(evaluationPresetId);
    const quiescence = resolveWorkerQuiescenceOptions(request.quiescenceMaxTacticalDepth);
    return {
      type: 'time-limited-iterative-deepening-alpha-beta-search-succeeded',
      requestId: request.requestId,
      result: {
        ...(quiescence === undefined
          ? search(request.state, request.maxDepth, request.timeLimitMilliseconds, evaluation)
          : search(
            request.state,
            request.maxDepth,
            request.timeLimitMilliseconds,
            evaluation,
            undefined,
            { quiescence }
          )),
        evaluationPresetId,
        quiescenceMaxTacticalDepth: quiescence?.maxTacticalDepth ?? null,
      },
    };
  } catch (error) {
    return toWorkerFailureResponse(request.requestId, error);
  }
}

import type { TimeLimitedIterativeDeepeningAlphaBetaSearchResult } from '../domain/shogi/twoPlyAlphaBetaAi';
import type { BoardState } from '../types/shogi';
import type { SearchEvaluationPresetId } from '../domain/shogi/searchEvaluationPresets';

/** The only tactical extensions exposed by the time-limited Worker contract. */
export type TimeLimitedSearchQuiescenceMaxTacticalDepth = 1 | 2;

export type PresetTimeLimitedSearchResult = TimeLimitedIterativeDeepeningAlphaBetaSearchResult & {
  readonly evaluationPresetId: SearchEvaluationPresetId;
  /** `null` means the Worker intentionally did not enable quiescence search. */
  readonly quiescenceMaxTacticalDepth: TimeLimitedSearchQuiescenceMaxTacticalDepth | null;
};

/** A structured-cloneable request sent from the UI thread to one search worker. */
export interface RunTimeLimitedIterativeDeepeningAlphaBetaSearchWorkerRequest {
  type: 'run-time-limited-iterative-deepening-alpha-beta-search';
  requestId: string;
  state: BoardState;
  maxDepth: number;
  timeLimitMilliseconds: number;
  /** Omitted by legacy callers: resolved to the shared default in the Worker. */
  evaluationPresetId?: SearchEvaluationPresetId;
  /** Omitted means quiescence search is disabled; only 1 and 2 are accepted. */
  quiescenceMaxTacticalDepth?: TimeLimitedSearchQuiescenceMaxTacticalDepth;
}

/** A completed time-limited search, preserving numeric values such as Infinity. */
export interface TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerSuccessResponse {
  type: 'time-limited-iterative-deepening-alpha-beta-search-succeeded';
  requestId: string;
  result: PresetTimeLimitedSearchResult;
}

/** A structured-cloneable representation of an error raised by the worker. */
export interface TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerFailureResponse {
  type: 'time-limited-iterative-deepening-alpha-beta-search-failed';
  requestId: string | null;
  errorName: string;
  errorMessage: string;
}

export type TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerRequest =
  RunTimeLimitedIterativeDeepeningAlphaBetaSearchWorkerRequest;

export type TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerResponse =
  | TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerSuccessResponse
  | TimeLimitedIterativeDeepeningAlphaBetaSearchWorkerFailureResponse;

